-- Orator: every database script, in the order they must run, in one file. Generated by npm run sql:bundle; edit the separate files instead.
-- Supabase → SQL Editor → New query → paste all of this → Run. Safe to run again: it never deletes your data.

-- ═════════ supabase/schema.sql ═════════
-- Orator accounts. Run once in the Supabase dashboard: SQL Editor → New query → paste → Run.
-- Creates a profile row for every new account and stops users from changing their own roles.

create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text not null default '',
  school text not null default '',
  roles text[] not null default '{student}',
  created_at timestamptz not null default now(),
  constraint profiles_roles_valid check (roles <@ array['student', 'judge', 'coach', 'director'] and cardinality(roles) > 0)
);

alter table public.profiles enable row level security;

drop policy if exists "Read own profile" on public.profiles;
create policy "Read own profile" on public.profiles for select to authenticated using (auth.uid() = id);

drop policy if exists "Update own profile" on public.profiles;
create policy "Update own profile" on public.profiles for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);

-- Signed-in users may edit their name and school only. Roles are set at sign-up and changed by an admin.
revoke all on public.profiles from anon, authenticated;
grant select on public.profiles to authenticated;
grant update (full_name, school) on public.profiles to authenticated;

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  requested text[];
  allowed text[];
begin
  select coalesce(array_agg(value), '{}') into requested
    from jsonb_array_elements_text(coalesce(new.raw_user_meta_data -> 'roles', '[]'::jsonb)) as value;
  select coalesce(array_agg(role), '{}') into allowed
    from unnest(array['student', 'judge', 'coach', 'director']) as role where role = any (requested);
  if cardinality(allowed) = 0 then allowed := array['student']; end if;
  insert into public.profiles (id, full_name, school, roles)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', ''), coalesce(new.raw_user_meta_data ->> 'school', ''), allowed)
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();


-- ═════════ supabase/ballots.sql ═════════
-- Orator ballots. Run once in the Supabase dashboard after schema.sql:
-- SQL Editor → New query → paste → Run. Safe to run again.
--
-- A judge owns one ballot per tournament, round, and room. They can edit it until they
-- submit it; after that it is locked. Coaches can read submitted ballot entries for
-- speakers from their own school. Private notes are readable by the judge alone.

create schema if not exists private;

create table if not exists public.ballots (
  id uuid primary key default gen_random_uuid(),
  judge_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  judge_name text not null default '',
  tournament text not null,
  round int not null check (round between 1 and 20),
  room text not null,
  event_id text not null,
  class_a boolean not null default false,
  status text not null default 'draft' check (status in ('draft', 'submitted')),
  submitted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (judge_id, tournament, round, room)
);

create table if not exists public.ballot_entries (
  ballot_id uuid not null references public.ballots (id) on delete cascade,
  speaker_code text not null,
  speaker_name text not null,
  school text not null default '',
  present boolean,                                  -- null until the judge checks the speaker in
  rank int check (rank between 1 and 10),           -- null for no-shows
  rating int check (rating between 35 and 50),
  time_seconds int check (time_seconds >= 0),
  time_penalty boolean not null default false,      -- lowered one rank for over/undertime
  section_marks int[] not null default '{}',        -- one 1–10 mark per criteria section
  reason text not null default '',
  disqualifications text[] not null default '{}',
  primary key (ballot_id, speaker_code),
  constraint ballot_entries_no_ties unique (ballot_id, rank) deferrable initially deferred
);

-- General comments, added after the first version of this script.
alter table public.ballot_entries add column if not exists comments text not null default '';

create table if not exists public.ballot_private_notes (
  ballot_id uuid not null references public.ballots (id) on delete cascade,
  speaker_code text not null,
  note text not null default '',
  primary key (ballot_id, speaker_code)
);

-- Helpers the row-level security policies call. They run with the table owner's rights so
-- the policies on one table can look at another without recursing into its policies.
create or replace function private.owns_ballot(target uuid, must_be_draft boolean) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ballots b where b.id = target and b.judge_id = (select auth.uid()) and (not must_be_draft or b.status = 'draft'));
$$;

create or replace function private.ballot_is_submitted(target uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ballots b where b.id = target and b.status = 'submitted');
$$;

-- The signed-in user's school in lower case if they are a coach, otherwise null.
create or replace function private.my_coach_school() returns text
language sql stable security definer set search_path = '' as $$
  select lower(p.school) from public.profiles p where p.id = (select auth.uid()) and 'coach' = any (p.roles) and p.school <> '';
$$;

create or replace function private.ballot_has_school(target uuid, wanted text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ballot_entries e where e.ballot_id = target and lower(e.school) = wanted);
$$;

revoke all on all functions in schema private from public, anon;
grant usage on schema private to authenticated;
grant execute on all functions in schema private to authenticated;

-- Stamp the judge on new ballots from their account, never from what the browser sends.
create or replace function public.stamp_ballot() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.judge_id := auth.uid();
    new.judge_name := coalesce((select p.full_name from public.profiles p where p.id = auth.uid()), '');
    new.status := 'draft';
    new.submitted_at := null;
  else
    new.judge_id := old.judge_id;
    new.judge_name := old.judge_name;
    new.created_at := old.created_at;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists stamp_ballot on public.ballots;
create trigger stamp_ballot before insert or update on public.ballots
  for each row execute function public.stamp_ballot();

-- Refuse to submit a ballot that breaks the NSAA rules the app also checks in the browser.
create or replace function public.check_ballot_submission() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  problem text;
begin
  if new.status = 'submitted' and old.status = 'draft' then
    select case
      when count(*) = 0 then 'The ballot has no speakers.'
      when bool_or(e.present is null) then 'Every speaker must be marked present or no-show.'
      when bool_or(e.present and e.time_seconds is null) then 'Every speaker needs a time.'
      when bool_or(e.present and char_length(btrim(e.comments)) + char_length(btrim(e.reason)) < 40) then 'Every speaker needs at least 40 characters of comments and reason for decision.'
      when bool_or(e.present and (cardinality(e.section_marks) <> 5 or exists (select 1 from unnest(e.section_marks) m where m is null or m < 1 or m > 10))) then 'Every speaker needs five section marks from 1 to 10.'
      -- The rating is the total of the section marks, and the NSAA scale starts at 35.
      when bool_or(e.present and e.rating is distinct from greatest(35, (select sum(m) from unnest(e.section_marks) m)::int)) then 'Each rating must equal the total of its section marks.'
      when bool_or(e.present and e.rank is null) then 'Every speaker who performed needs a rank.'
      when count(*) filter (where e.present) <> count(distinct e.rank) filter (where e.present) then 'There may be no ties in rank.'
      when coalesce(max(e.rank) filter (where e.present), 0) <> count(*) filter (where e.present) then 'Ranks must run from 1 with no gaps.'
    end into problem
    from public.ballot_entries e where e.ballot_id = new.id;
    if problem is null and exists (
      select 1 from public.ballot_entries a join public.ballot_entries b on b.ballot_id = a.ballot_id
      where a.ballot_id = new.id and a.present and b.present and a.rank < b.rank and a.rating < b.rating and not b.time_penalty  -- a time penalty lowers an entry one rank
    ) then problem := 'A speaker with a lower rating is ranked above one with a higher rating.'; end if;
    if problem is not null then raise exception '%', problem using errcode = 'check_violation'; end if;
    new.submitted_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists check_ballot_submission on public.ballots;
create trigger check_ballot_submission before update on public.ballots
  for each row execute function public.check_ballot_submission();

revoke all on function public.stamp_ballot() from public, anon, authenticated;
revoke all on function public.check_ballot_submission() from public, anon, authenticated;

alter table public.ballots enable row level security;
alter table public.ballot_entries enable row level security;
alter table public.ballot_private_notes enable row level security;

revoke all on public.ballots, public.ballot_entries, public.ballot_private_notes from anon, authenticated;
grant select, insert, update, delete on public.ballots, public.ballot_entries, public.ballot_private_notes to authenticated;

-- Ballots: only accounts with the judge role can create one; a judge reads their own and
-- edits them while they are drafts.
drop policy if exists "Judges read own ballots" on public.ballots;
create policy "Judges read own ballots" on public.ballots for select to authenticated
  using (judge_id = (select auth.uid()));

drop policy if exists "Coaches read submitted ballots for their school" on public.ballots;
create policy "Coaches read submitted ballots for their school" on public.ballots for select to authenticated
  using (status = 'submitted' and private.ballot_has_school(id, (select private.my_coach_school())));

drop policy if exists "Judges create ballots" on public.ballots;
create policy "Judges create ballots" on public.ballots for insert to authenticated
  with check (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and 'judge' = any (p.roles)));

drop policy if exists "Judges edit own draft ballots" on public.ballots;
create policy "Judges edit own draft ballots" on public.ballots for update to authenticated
  using (judge_id = (select auth.uid()) and status = 'draft') with check (judge_id = (select auth.uid()));

drop policy if exists "Judges delete own draft ballots" on public.ballots;
create policy "Judges delete own draft ballots" on public.ballots for delete to authenticated
  using (judge_id = (select auth.uid()) and status = 'draft');

-- Entries: the judge reads their own and changes them while the ballot is a draft.
drop policy if exists "Judges read own entries" on public.ballot_entries;
create policy "Judges read own entries" on public.ballot_entries for select to authenticated
  using (private.owns_ballot(ballot_id, false));

drop policy if exists "Coaches read submitted entries for their school" on public.ballot_entries;
create policy "Coaches read submitted entries for their school" on public.ballot_entries for select to authenticated
  using (lower(school) = (select private.my_coach_school()) and private.ballot_is_submitted(ballot_id));

drop policy if exists "Judges add entries to draft ballots" on public.ballot_entries;
create policy "Judges add entries to draft ballots" on public.ballot_entries for insert to authenticated
  with check (private.owns_ballot(ballot_id, true));

drop policy if exists "Judges edit entries on draft ballots" on public.ballot_entries;
create policy "Judges edit entries on draft ballots" on public.ballot_entries for update to authenticated
  using (private.owns_ballot(ballot_id, true)) with check (private.owns_ballot(ballot_id, true));

drop policy if exists "Judges remove entries from draft ballots" on public.ballot_entries;
create policy "Judges remove entries from draft ballots" on public.ballot_entries for delete to authenticated
  using (private.owns_ballot(ballot_id, true));

-- Private notes: the judge only, always.
drop policy if exists "Judges read own notes" on public.ballot_private_notes;
create policy "Judges read own notes" on public.ballot_private_notes for select to authenticated
  using (private.owns_ballot(ballot_id, false));

drop policy if exists "Judges add own notes" on public.ballot_private_notes;
create policy "Judges add own notes" on public.ballot_private_notes for insert to authenticated
  with check (private.owns_ballot(ballot_id, false));

drop policy if exists "Judges edit own notes" on public.ballot_private_notes;
create policy "Judges edit own notes" on public.ballot_private_notes for update to authenticated
  using (private.owns_ballot(ballot_id, false)) with check (private.owns_ballot(ballot_id, false));

drop policy if exists "Judges remove own notes" on public.ballot_private_notes;
create policy "Judges remove own notes" on public.ballot_private_notes for delete to authenticated
  using (private.owns_ballot(ballot_id, false));


-- ═════════ supabase/tournaments.sql ═════════
-- Orator tournaments, director approval, entries, and schedules.
-- Run once in the Supabase dashboard after schema.sql and ballots.sql:
-- SQL Editor → New query → paste → Run. Safe to run again.
--
-- A director creates a tournament. Coaches, judges, and students ask to join it and the
-- director approves or declines each request. Approved coaches enter their own school's
-- students while registration is open. The director builds and publishes the schedule;
-- approved members can then see it.

create schema if not exists private;

create table if not exists public.tournaments (
  id uuid primary key default gen_random_uuid(),
  director_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 120),
  date text not null default '',
  host text not null default '',
  rounds int not null default 3 check (rounds between 1 and 6),
  section_size int not null default 6 check (section_size between 3 and 10),
  max_entries int not null default 4 check (max_entries between 1 and 4),
  event_ids text[] not null default '{}',
  status text not null default 'registration' check (status in ('registration', 'scheduled', 'running', 'finished')),
  created_at timestamptz not null default now()
);

create table if not exists public.tournament_members (
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  role text not null check (role in ('coach', 'student', 'judge')),
  school text not null default '',
  display_name text not null default '',
  status text not null default 'pending' check (status in ('pending', 'approved', 'declined')),
  entries_sent boolean not null default false,       -- a coach's "these entries are final"
  created_at timestamptz not null default now(),
  primary key (tournament_id, user_id, role)
);

-- Added after the first version of this script: a coach's decision to show results to their students.
alter table public.tournament_members add column if not exists results_released boolean not null default false;
-- A judge's event preferences, used only to choose which final they judge.
alter table public.tournament_members add column if not exists event_preferences jsonb not null default '[]'::jsonb;

create table if not exists public.entries (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  school text not null check (char_length(btrim(school)) > 0),
  student text not null check (char_length(btrim(student)) > 0),
  event_id text not null,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
-- A student may enter each event once.
create unique index if not exists entries_one_per_event on public.entries (tournament_id, lower(school), lower(student), event_id);

create table if not exists public.sections (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  round int not null check (round between 1 and 6),
  event_id text not null,
  label text not null default '',
  room text not null default '',
  judge_id uuid references auth.users (id) on delete set null,
  judge_name text not null default '',
  entry_ids uuid[] not null default '{}',             -- speaking order
  position int not null default 0
);
create index if not exists sections_by_tournament on public.sections (tournament_id, round, position);

-- Added Nov 2026, after the interview with a head coach:
-- the director opens and closes entries whenever they choose; judges only see a rating if the director turns it on.
alter table public.tournaments add column if not exists entries_open boolean not null default true;
alter table public.tournaments add column if not exists show_rating boolean not null default false;
-- Varsity or novice. Each event runs separately in each division, with its own rooms and final.
alter table public.entries add column if not exists division text not null default 'varsity';
alter table public.sections add column if not exists division text not null default 'varsity';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'entries_division_check') then
    alter table public.entries add constraint entries_division_check check (division in ('varsity', 'novice'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'sections_division_check') then
    alter table public.sections add constraint sections_division_check check (division in ('varsity', 'novice'));
  end if;
end $$;
-- A "clean" judge knows none of the competitors; otherwise a judge lists other schools whose students they know.
alter table public.tournament_members add column if not exists clean_judge boolean not null default false;
alter table public.tournament_members add column if not exists known_schools text[] not null default '{}';

-- Helpers for the row-level security policies. They run with the table owner's rights so
-- one table's policy can check another table without recursing into its policies.
create or replace function private.is_director(target uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tournaments t where t.id = target and t.director_id = (select auth.uid()));
$$;

create or replace function private.tournament_status(target uuid) returns text
language sql stable security definer set search_path = '' as $$
  select t.status from public.tournaments t where t.id = target;
$$;

create or replace function private.entries_open(target uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select t.entries_open and t.status = 'registration' from public.tournaments t where t.id = target), false);
$$;

create or replace function private.is_approved_member(target uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tournament_members m where m.tournament_id = target and m.user_id = (select auth.uid()) and m.status = 'approved');
$$;

-- The school (lower case) the signed-in user is approved to coach at this tournament, or null.
create or replace function private.approved_coach_school(target uuid) returns text
language sql stable security definer set search_path = '' as $$
  select lower(m.school) from public.tournament_members m
  where m.tournament_id = target and m.user_id = (select auth.uid()) and m.role = 'coach' and m.status = 'approved' and m.school <> '';
$$;

revoke all on all functions in schema private from public, anon;
grant usage on schema private to authenticated;
grant execute on all functions in schema private to authenticated;

-- Tournaments: the director is always the signed-in account, and only accounts with the director role may create one.
create or replace function public.stamp_tournament() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.profiles p where p.id = auth.uid() and 'director' = any (p.roles)) then
      raise exception 'Only accounts with the Director role can create a tournament.' using errcode = 'insufficient_privilege';
    end if;
    new.director_id := auth.uid();
    new.status := 'registration';
  else
    new.director_id := old.director_id;
  end if;
  return new;
end;
$$;
drop trigger if exists stamp_tournament on public.tournaments;
create trigger stamp_tournament before insert or update on public.tournaments
  for each row execute function public.stamp_tournament();

-- Membership requests always start pending, under the requester's own name, for a role their account has.
-- Afterwards only the director can change the decision; the member may only flag their entries as sent.
create or replace function public.stamp_member() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.profiles p where p.id = auth.uid() and new.role = any (p.roles)) then
      raise exception 'Your account does not have the % role.', new.role using errcode = 'insufficient_privilege';
    end if;
    new.user_id := auth.uid();
    new.status := 'pending';
    new.entries_sent := false;
    new.school := btrim(new.school);
    new.display_name := coalesce((select p.full_name from public.profiles p where p.id = auth.uid()), '');
  else
    new.tournament_id := old.tournament_id; new.user_id := old.user_id; new.role := old.role; new.display_name := old.display_name;
    if not private.is_director(old.tournament_id) then
      new.status := old.status; new.school := old.school;
    end if;
    -- A coach releases results to their students, and only once the tournament has ended.
    if new.results_released and not old.results_released then
      if old.role <> 'coach' or old.status <> 'approved' then
        raise exception 'Only an approved coach can release results.' using errcode = 'insufficient_privilege';
      end if;
      if private.tournament_status(old.tournament_id) <> 'finished' then
        raise exception 'Results can be released once the tournament has ended.' using errcode = 'check_violation';
      end if;
    end if;
  end if;
  return new;
end;
$$;
drop trigger if exists stamp_member on public.tournament_members;
create trigger stamp_member before insert or update on public.tournament_members
  for each row execute function public.stamp_member();

-- Entries: the event must be offered and the student must be under the tournament's cap.
create or replace function public.check_entry() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  t public.tournaments;
begin
  select * into t from public.tournaments where id = new.tournament_id;
  if t.id is null then raise exception 'That tournament does not exist.'; end if;
  new.student := btrim(new.student); new.school := btrim(new.school); new.created_by := auth.uid();
  if t.status <> 'registration' then raise exception 'Registration is closed for this tournament.' using errcode = 'check_violation'; end if;
  -- Closed entries stop coaches; the director can still add a late entry.
  if not t.entries_open and t.director_id is distinct from auth.uid() then raise exception 'Entries are closed for this tournament.' using errcode = 'check_violation'; end if;
  -- A student is in one division: every event they enter is in the same one.
  if exists (select 1 from public.entries e where e.tournament_id = new.tournament_id and lower(e.school) = lower(new.school) and lower(e.student) = lower(new.student) and e.division <> new.division) then
    raise exception '% is already entered as %.', new.student, (select e.division from public.entries e where e.tournament_id = new.tournament_id and lower(e.school) = lower(new.school) and lower(e.student) = lower(new.student) limit 1) using errcode = 'check_violation';
  end if;
  if not (new.event_id = any (t.event_ids)) then raise exception 'That event is not offered at this tournament.' using errcode = 'check_violation'; end if;
  if (select count(*) from public.entries e where e.tournament_id = new.tournament_id and lower(e.school) = lower(new.school) and lower(e.student) = lower(new.student)) >= t.max_entries then
    raise exception '% is already in % events, the most this tournament allows.', new.student, t.max_entries using errcode = 'check_violation';
  end if;
  return new;
end;
$$;
drop trigger if exists check_entry on public.entries;
create trigger check_entry before insert on public.entries
  for each row execute function public.check_entry();

revoke all on function public.stamp_tournament() from public, anon, authenticated;
revoke all on function public.stamp_member() from public, anon, authenticated;
revoke all on function public.check_entry() from public, anon, authenticated;

alter table public.tournaments enable row level security;
alter table public.tournament_members enable row level security;
alter table public.entries enable row level security;
alter table public.sections enable row level security;

revoke all on public.tournaments, public.tournament_members, public.entries, public.sections from anon, authenticated;
grant select, insert, update, delete on public.tournaments, public.tournament_members, public.entries, public.sections to authenticated;

-- Tournaments: any signed-in user can see the list (so they can ask to join); only the director changes one.
drop policy if exists "Signed-in users see tournaments" on public.tournaments;
create policy "Signed-in users see tournaments" on public.tournaments for select to authenticated using (true);
drop policy if exists "Directors create tournaments" on public.tournaments;
create policy "Directors create tournaments" on public.tournaments for insert to authenticated with check (true);
drop policy if exists "Directors edit their tournaments" on public.tournaments;
create policy "Directors edit their tournaments" on public.tournaments for update to authenticated
  using (director_id = (select auth.uid())) with check (director_id = (select auth.uid()));
drop policy if exists "Directors delete their tournaments" on public.tournaments;
create policy "Directors delete their tournaments" on public.tournaments for delete to authenticated using (director_id = (select auth.uid()));

-- Members: people see their own requests; the director sees and decides all of them.
drop policy if exists "Members see their own requests" on public.tournament_members;
create policy "Members see their own requests" on public.tournament_members for select to authenticated
  using (user_id = (select auth.uid()) or private.is_director(tournament_id));
drop policy if exists "People ask to join" on public.tournament_members;
create policy "People ask to join" on public.tournament_members for insert to authenticated with check (true);
drop policy if exists "Directors decide requests" on public.tournament_members;
create policy "Directors decide requests" on public.tournament_members for update to authenticated
  using (user_id = (select auth.uid()) or private.is_director(tournament_id))
  with check (user_id = (select auth.uid()) or private.is_director(tournament_id));
drop policy if exists "Withdraw or remove a request" on public.tournament_members;
create policy "Withdraw or remove a request" on public.tournament_members for delete to authenticated
  using ((user_id = (select auth.uid()) and status = 'pending') or private.is_director(tournament_id));

-- Entries: the director sees all; an approved coach sees and edits their own school's while registration
-- is open; every approved member sees the field once the schedule is published.
drop policy if exists "Who can see entries" on public.entries;
create policy "Who can see entries" on public.entries for select to authenticated
  using (private.is_director(tournament_id)
    or lower(school) = (select private.approved_coach_school(tournament_id))
    or (private.is_approved_member(tournament_id) and private.tournament_status(tournament_id) <> 'registration'));
drop policy if exists "Coaches enter their own school" on public.entries;
create policy "Coaches enter their own school" on public.entries for insert to authenticated
  with check (private.is_director(tournament_id) or lower(btrim(school)) = (select private.approved_coach_school(tournament_id)));
drop policy if exists "Coaches withdraw their own entries" on public.entries;
create policy "Coaches withdraw their own entries" on public.entries for delete to authenticated
  using (private.tournament_status(tournament_id) = 'registration'
    and (private.is_director(tournament_id) or (private.entries_open(tournament_id) and lower(school) = (select private.approved_coach_school(tournament_id)))));

-- Schedule: the director builds it; approved members see it once it is published.
drop policy if exists "Who can see the schedule" on public.sections;
create policy "Who can see the schedule" on public.sections for select to authenticated
  using (private.is_director(tournament_id)
    or (private.is_approved_member(tournament_id) and private.tournament_status(tournament_id) <> 'registration'));
drop policy if exists "Directors build the schedule" on public.sections;
create policy "Directors build the schedule" on public.sections for insert to authenticated with check (private.is_director(tournament_id));
drop policy if exists "Directors change the schedule" on public.sections;
create policy "Directors change the schedule" on public.sections for update to authenticated
  using (private.is_director(tournament_id)) with check (private.is_director(tournament_id));
drop policy if exists "Directors clear the schedule" on public.sections;
create policy "Directors clear the schedule" on public.sections for delete to authenticated using (private.is_director(tournament_id));

-- Ballots filled in for a scheduled room carry the tournament and room they belong to, so the
-- director can work out breaks and finals from them. (The ballots table comes from ballots.sql.)
alter table public.ballots add column if not exists tournament_id uuid references public.tournaments (id) on delete set null;
alter table public.ballots add column if not exists section_id uuid references public.sections (id) on delete set null;

create or replace function private.directs_ballot(target uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ballots b join public.tournaments t on t.id = b.tournament_id where b.id = target and t.director_id = (select auth.uid()));
$$;
revoke all on function private.directs_ballot(uuid) from public, anon;
grant execute on function private.directs_ballot(uuid) to authenticated;

-- A judge may only attach a ballot to a room they were assigned in a tournament they were approved for.
create or replace function public.check_ballot_room() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.section_id is not null and not exists (select 1 from public.sections s where s.id = new.section_id and s.tournament_id = new.tournament_id and s.judge_id = auth.uid()) then
    raise exception 'You are not the judge assigned to that room.' using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;
drop trigger if exists check_ballot_room on public.ballots;
create trigger check_ballot_room before insert on public.ballots
  for each row execute function public.check_ballot_room();
revoke all on function public.check_ballot_room() from public, anon, authenticated;

-- Directors read submitted ballots for their own tournament. Private notes stay with the judge.
drop policy if exists "Directors read ballots for their tournament" on public.ballots;
create policy "Directors read ballots for their tournament" on public.ballots for select to authenticated
  using (status = 'submitted' and tournament_id is not null and private.is_director(tournament_id));
drop policy if exists "Directors read entries for their tournament" on public.ballot_entries;
create policy "Directors read entries for their tournament" on public.ballot_entries for select to authenticated
  using (private.ballot_is_submitted(ballot_id) and private.directs_ballot(ballot_id));

-- Students see their own ballots from a tournament once it has finished and their coach has released
-- results. "Their own" means an entry under the name they joined with, at the school they were
-- approved for. The joining name is fixed when they ask to join, so renaming an account later
-- does not open up a teammate's ballots.
create or replace function private.student_can_read(target uuid, speaker text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from public.ballots b
    join public.tournaments t on t.id = b.tournament_id
    join public.tournament_members me on me.tournament_id = t.id and me.user_id = (select auth.uid()) and me.role = 'student' and me.status = 'approved'
    join public.entries e on e.tournament_id = t.id and e.id::text = speaker and lower(e.school) = lower(me.school) and lower(e.student) = lower(me.display_name)
    where b.id = target and b.status = 'submitted' and t.status = 'finished'
      and exists (select 1 from public.tournament_members c where c.tournament_id = t.id and c.role = 'coach' and c.status = 'approved' and lower(c.school) = lower(me.school) and c.results_released)
  );
$$;
create or replace function private.student_can_read_ballot(target uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.ballot_entries be where be.ballot_id = target and private.student_can_read(target, be.speaker_code));
$$;
revoke all on function private.student_can_read(uuid, text) from public, anon;
revoke all on function private.student_can_read_ballot(uuid) from public, anon;
grant execute on function private.student_can_read(uuid, text) to authenticated;
grant execute on function private.student_can_read_ballot(uuid) to authenticated;

drop policy if exists "Students read their own released entries" on public.ballot_entries;
create policy "Students read their own released entries" on public.ballot_entries for select to authenticated
  using (private.student_can_read(ballot_id, speaker_code));
drop policy if exists "Students read ballots holding their released entries" on public.ballots;
create policy "Students read ballots holding their released entries" on public.ballots for select to authenticated
  using (tournament_id is not null and private.student_can_read_ballot(id));

-- Notes from the director: changes to the published schedule, and entries opening or closing.
-- Every approved member of the tournament can read them; only the director writes them.
create table if not exists public.tournament_updates (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  kind text not null default 'schedule' check (kind in ('schedule', 'entries')),
  message text not null check (char_length(btrim(message)) between 1 and 300),
  created_at timestamptz not null default now()
);
create index if not exists tournament_updates_recent on public.tournament_updates (tournament_id, created_at desc);
alter table public.tournament_updates enable row level security;
revoke all on public.tournament_updates from anon, authenticated;
grant select, insert on public.tournament_updates to authenticated;
drop policy if exists "Members read the director's updates" on public.tournament_updates;
create policy "Members read the director's updates" on public.tournament_updates for select to authenticated
  using (private.is_director(tournament_id) or private.is_approved_member(tournament_id));
drop policy if exists "Directors post updates" on public.tournament_updates;
create policy "Directors post updates" on public.tournament_updates for insert to authenticated
  with check (private.is_director(tournament_id));

-- ── Issue reports. Anyone approved for the tournament (and the director) can report one; the director
-- sees and resolves them all, and each reporter can see their own.
create table if not exists public.issues (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  reporter_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  reporter_name text not null default '',
  reporter_role text not null default '',
  kind text not null check (kind in ('no-judge', 'injury', 'schedule', 'ballot', 'other')),
  location text not null check (char_length(btrim(location)) between 1 and 120),
  detail text not null default '' check (char_length(detail) <= 2000),
  status text not null default 'open' check (status in ('open', 'resolved')),
  created_at timestamptz not null default now()
);
create index if not exists issues_by_tournament on public.issues (tournament_id, created_at desc);

create or replace function public.stamp_issue() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.reporter_id := auth.uid();
    new.reporter_name := coalesce((select p.full_name from public.profiles p where p.id = auth.uid()), '');
    new.status := 'open';
  else
    -- Only the status changes after a report is sent.
    new.tournament_id := old.tournament_id; new.reporter_id := old.reporter_id; new.reporter_name := old.reporter_name; new.reporter_role := old.reporter_role;
    new.kind := old.kind; new.location := old.location; new.detail := old.detail; new.created_at := old.created_at;
  end if;
  return new;
end;
$$;
drop trigger if exists stamp_issue on public.issues;
create trigger stamp_issue before insert or update on public.issues for each row execute function public.stamp_issue();
revoke all on function public.stamp_issue() from public, anon, authenticated;

alter table public.issues enable row level security;
revoke all on public.issues from anon, authenticated;
grant select, insert, update on public.issues to authenticated;
drop policy if exists "Members report issues" on public.issues;
create policy "Members report issues" on public.issues for insert to authenticated
  with check (private.is_director(tournament_id) or private.is_approved_member(tournament_id));
drop policy if exists "Director and reporter read issues" on public.issues;
create policy "Director and reporter read issues" on public.issues for select to authenticated
  using (private.is_director(tournament_id) or reporter_id = (select auth.uid()));
drop policy if exists "Director resolves issues" on public.issues;
create policy "Director resolves issues" on public.issues for update to authenticated
  using (private.is_director(tournament_id)) with check (private.is_director(tournament_id));

-- ── Judge check-in on the day. Only the director marks a judge as arrived.
alter table public.tournament_members add column if not exists checked_in boolean not null default false;
create or replace function public.guard_check_in() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not private.is_director(old.tournament_id) then new.checked_in := old.checked_in; end if;
  return new;
end;
$$;
drop trigger if exists guard_check_in on public.tournament_members;
create trigger guard_check_in before update on public.tournament_members for each row execute function public.guard_check_in();
revoke all on function public.guard_check_in() from public, anon, authenticated;

-- ── Practice goals a coach sets for a student. They belong to the student (by name and school), not to
-- one tournament, so they carry across the season. A coach approved at that school (at any tournament)
-- manages them; the student approved under that name and school can read them and tick them off.
create table if not exists public.practice_goals (
  id uuid primary key default gen_random_uuid(),
  school text not null check (char_length(btrim(school)) > 0),
  student text not null check (char_length(btrim(student)) > 0),
  event_id text not null default '',
  goal text not null check (char_length(btrim(goal)) between 1 and 300),
  done boolean not null default false,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists practice_goals_by_student on public.practice_goals (lower(school), lower(student));

create or replace function private.coaches_school(target text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tournament_members m where m.user_id = (select auth.uid()) and m.role = 'coach' and m.status = 'approved' and lower(m.school) = lower(btrim(target)));
$$;
create or replace function private.is_student(target_school text, target_student text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tournament_members m where m.user_id = (select auth.uid()) and m.role = 'student' and m.status = 'approved'
    and lower(m.school) = lower(btrim(target_school)) and lower(m.display_name) = lower(btrim(target_student)));
$$;
revoke all on function private.coaches_school(text) from public, anon;
revoke all on function private.is_student(text, text) from public, anon;
grant execute on function private.coaches_school(text) to authenticated;
grant execute on function private.is_student(text, text) to authenticated;

-- A student may only tick a goal off (or back on); everything else stays as the coach wrote it.
create or replace function public.guard_goal() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.school := btrim(new.school); new.student := btrim(new.student); new.goal := btrim(new.goal); new.created_by := auth.uid(); new.created_at := now();
  elsif not private.coaches_school(old.school) then
    new.school := old.school; new.student := old.student; new.event_id := old.event_id; new.goal := old.goal;
  end if;
  if tg_op = 'UPDATE' then new.created_by := old.created_by; new.created_at := old.created_at; end if;
  return new;
end;
$$;
drop trigger if exists guard_goal on public.practice_goals;
create trigger guard_goal before insert or update on public.practice_goals for each row execute function public.guard_goal();
revoke all on function public.guard_goal() from public, anon, authenticated;

alter table public.practice_goals enable row level security;
revoke all on public.practice_goals from anon, authenticated;
grant select, insert, update, delete on public.practice_goals to authenticated;
drop policy if exists "Coach and student read goals" on public.practice_goals;
create policy "Coach and student read goals" on public.practice_goals for select to authenticated
  using (private.coaches_school(school) or private.is_student(school, student));
drop policy if exists "Coaches set goals" on public.practice_goals;
create policy "Coaches set goals" on public.practice_goals for insert to authenticated with check (private.coaches_school(school));
drop policy if exists "Coach and student update goals" on public.practice_goals;
create policy "Coach and student update goals" on public.practice_goals for update to authenticated
  using (private.coaches_school(school) or private.is_student(school, student))
  with check (private.coaches_school(school) or private.is_student(school, student));
drop policy if exists "Coaches remove goals" on public.practice_goals;
create policy "Coaches remove goals" on public.practice_goals for delete to authenticated using (private.coaches_school(school));


-- ═════════ supabase/fixes.sql ═════════
-- Director settings saved with the tournament: fees, judges per final, the team-point scale,
-- whether novice finals earn team points. Run after tournaments.sql. Safe to run again.
alter table public.tournaments add column if not exists settings jsonb not null default '{}'::jsonb;

-- ── Linking student accounts to the roster. A student's entries, ballots and practice goals are
-- matched by name and school. If the name on their account isn't spelled the way their coach entered
-- it, the coach links the account to the right roster name. Only the coach (or director) can set it.
alter table public.tournament_members add column if not exists roster_name text not null default '';

-- The name a student member is matched by: the roster name their coach linked, else their account name.
create or replace function private.match_name(member public.tournament_members) returns text
language sql immutable set search_path = '' as $$ select lower(btrim(coalesce(nullif(member.roster_name, ''), member.display_name))) $$;

create or replace function public.guard_roster_name() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.roster_name is distinct from old.roster_name
     and not (private.is_director(old.tournament_id) or (old.role = 'student' and private.coaches_school(old.school))) then
    new.roster_name := old.roster_name;
  end if;
  return new;
end;
$$;
drop trigger if exists guard_roster_name on public.tournament_members;
create trigger guard_roster_name before update on public.tournament_members for each row execute function public.guard_roster_name();
revoke all on function public.guard_roster_name() from public, anon, authenticated;

-- A coach sees the student accounts approved at their own school for a tournament.
create or replace function public.school_students(target uuid)
returns table (user_id uuid, display_name text, roster_name text)
language sql stable security definer set search_path = '' as $$
  select m.user_id, m.display_name, m.roster_name from public.tournament_members m
  where m.tournament_id = target and m.role = 'student' and m.status = 'approved'
    and exists (select 1 from public.tournament_members c where c.tournament_id = target and c.user_id = (select auth.uid()) and c.role = 'coach' and c.status = 'approved' and lower(c.school) = lower(m.school))
  order by m.display_name;
$$;

-- A coach links one of their students to a roster name ('' to unlink). The name must be on that school's entries.
create or replace function public.link_student(target uuid, student uuid, name text) returns void
language plpgsql security definer set search_path = '' as $$
declare m public.tournament_members;
begin
  select * into m from public.tournament_members where tournament_id = target and user_id = student and role = 'student';
  if m.user_id is null or not exists (select 1 from public.tournament_members c where c.tournament_id = target and c.user_id = auth.uid() and c.role = 'coach' and c.status = 'approved' and lower(c.school) = lower(m.school)) then
    raise exception 'Only the coach of this student''s school can link them.' using errcode = 'insufficient_privilege';
  end if;
  if btrim(name) <> '' and not exists (select 1 from public.entries e where e.tournament_id = target and lower(e.school) = lower(m.school) and lower(e.student) = lower(btrim(name))) then
    raise exception '% isn''t on your entries for this tournament.', btrim(name) using errcode = 'check_violation';
  end if;
  update public.tournament_members set roster_name = btrim(name) where tournament_id = target and user_id = student and role = 'student';
end;
$$;
revoke all on function public.school_students(uuid) from public, anon;
revoke all on function public.link_student(uuid, uuid, text) from public, anon;
grant execute on function public.school_students(uuid) to authenticated;
grant execute on function public.link_student(uuid, uuid, text) to authenticated;

-- Released ballots and practice goals now follow the linked roster name.
create or replace function private.student_can_read(target uuid, speaker text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from public.ballots b
    join public.tournaments t on t.id = b.tournament_id
    join public.tournament_members me on me.tournament_id = t.id and me.user_id = (select auth.uid()) and me.role = 'student' and me.status = 'approved'
    join public.entries e on e.tournament_id = t.id and e.id::text = speaker and lower(e.school) = lower(me.school) and lower(e.student) = private.match_name(me)
    where b.id = target and b.status = 'submitted' and t.status = 'finished'
      and exists (select 1 from public.tournament_members c where c.tournament_id = t.id and c.role = 'coach' and c.status = 'approved' and lower(c.school) = lower(me.school) and c.results_released)
  );
$$;
create or replace function private.is_student(target_school text, target_student text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tournament_members m where m.user_id = (select auth.uid()) and m.role = 'student' and m.status = 'approved'
    and lower(m.school) = lower(btrim(target_school)) and private.match_name(m) = lower(btrim(target_student)));
$$;
revoke all on function private.match_name(public.tournament_members) from public, anon;
grant execute on function private.match_name(public.tournament_members) to authenticated;

-- ── The speech's title or thesis on each ballot entry, as the speaker gave it or the judge wrote it down.
alter table public.ballot_entries add column if not exists speech_title text not null default '';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'ballot_entries_speech_title_length') then
    alter table public.ballot_entries add constraint ballot_entries_speech_title_length check (char_length(speech_title) <= 200);
  end if;
end $$;


-- ═════════ supabase/calendar.sql ═════════
-- Orator public tournament calendar and open coach registration.
-- Run in the Supabase SQL Editor after tournaments.sql. Safe to run again.
--
-- Directors choose whether their tournament is listed on the public calendar (#/calendar), which
-- anyone can read without an account. Only listed tournaments and only the columns below are public:
-- never entries, members, names, or emails. A director may also approve coaches automatically:
-- a coach's request to register their school is then approved at once, while judges and students
-- still wait for the director.

-- ── Listing details on each tournament
alter table public.tournaments add column if not exists listed boolean not null default false;
-- Tournaments created before the calendar existed stay off it until the director lists them; new ones are listed.
alter table public.tournaments alter column listed set default true;
alter table public.tournaments add column if not exists city text not null default '';
-- A real date for sorting and filtering. `date` stays as the text shown to people.
alter table public.tournaments add column if not exists start_date date;
alter table public.tournaments add column if not exists registration_deadline date;
alter table public.tournaments add column if not exists notes text not null default '';
alter table public.tournaments add column if not exists auto_approve_coaches boolean not null default false;
-- What the host charges ({ entry, school, judge, entriesPerJudge }, in dollars). Null means Orator's defaults.
alter table public.tournaments add column if not exists fees jsonb;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'tournaments_city_length') then
    alter table public.tournaments add constraint tournaments_city_length check (char_length(city) <= 80);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'tournaments_notes_length') then
    alter table public.tournaments add constraint tournaments_notes_length check (char_length(notes) <= 600);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'tournaments_fees_object') then
    alter table public.tournaments add constraint tournaments_fees_object check (fees is null or jsonb_typeof(fees) = 'object');
  end if;
end $$;
create index if not exists tournaments_listed_by_date on public.tournaments (start_date) where listed;

-- ── The public calendar. Anyone (signed in or not) can call this; it returns listed tournaments only,
-- with safe columns only, plus how many schools have a coach approved (a count, never names).
create or replace function public.list_public_tournaments()
returns table (
  id uuid, name text, date text, start_date date, host text, city text, registration_deadline date, notes text,
  event_ids text[], max_entries int, rounds int, status text, entries_open boolean, auto_approve_coaches boolean,
  entry_fee numeric, judge_fee numeric, school_fee numeric, schools_registered int
)
language sql stable security definer set search_path = '' as $$
  select t.id, t.name, t.date, t.start_date, t.host, t.city, t.registration_deadline, t.notes,
    t.event_ids, t.max_entries, t.rounds, t.status, t.entries_open, t.auto_approve_coaches,
    case when jsonb_typeof(t.fees -> 'entry') = 'number' then (t.fees ->> 'entry')::numeric end,
    case when jsonb_typeof(t.fees -> 'judge') = 'number' then (t.fees ->> 'judge')::numeric end,
    case when jsonb_typeof(t.fees -> 'school') = 'number' then (t.fees ->> 'school')::numeric end,
    (select count(distinct lower(m.school))::int from public.tournament_members m
      where m.tournament_id = t.id and m.role = 'coach' and m.status = 'approved' and m.school <> '')
  from public.tournaments t
  where t.listed
  order by t.start_date nulls last, t.created_at desc;
$$;
revoke all on function public.list_public_tournaments() from public;
grant execute on function public.list_public_tournaments() to anon, authenticated;

-- ── Membership requests. Same rules as tournaments.sql, plus one: when the director has turned on
-- "Approve coaches automatically", a coach's request is approved straight away, as long as registration
-- is still open and no other account has ever asked to coach that school at this tournament (that request
-- waits for the director, so nobody can take over another school's entries). Judges and students always wait.
create or replace function public.stamp_member() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.profiles p where p.id = auth.uid() and new.role = any (p.roles)) then
      raise exception 'Your account does not have the % role.', new.role using errcode = 'insufficient_privilege';
    end if;
    new.user_id := auth.uid();
    new.status := 'pending';
    new.entries_sent := false;
    new.school := btrim(new.school);
    new.display_name := coalesce((select p.full_name from public.profiles p where p.id = auth.uid()), '');
    if new.role = 'coach' and new.school <> ''
      and exists (select 1 from public.tournaments t where t.id = new.tournament_id and t.auto_approve_coaches and t.status = 'registration')
      and not exists (select 1 from public.tournament_members m where m.tournament_id = new.tournament_id and m.role = 'coach'
        and m.user_id <> new.user_id and lower(m.school) = lower(new.school)) then
      new.status := 'approved';
    end if;
  else
    new.tournament_id := old.tournament_id; new.user_id := old.user_id; new.role := old.role; new.display_name := old.display_name;
    if not private.is_director(old.tournament_id) then
      new.status := old.status; new.school := old.school;
    end if;
    -- A coach releases results to their students, and only once the tournament has ended.
    if new.results_released and not old.results_released then
      if old.role <> 'coach' or old.status <> 'approved' then
        raise exception 'Only an approved coach can release results.' using errcode = 'insufficient_privilege';
      end if;
      if private.tournament_status(old.tournament_id) <> 'finished' then
        raise exception 'Results can be released once the tournament has ended.' using errcode = 'check_violation';
      end if;
    end if;
  end if;
  return new;
end;
$$;
revoke all on function public.stamp_member() from public, anon, authenticated;


-- ═════════ supabase/public_results.sql ═════════
-- Orator public results: final placings and team points, published by the director.
-- Run in the Supabase dashboard after tournaments.sql: SQL Editor → New query → paste → Run.
-- Safe to run again.
--
-- "Results are public, but ballots and specific rankings are private."
-- Once a tournament has ended, its director publishes a snapshot of each contest's final
-- placings (place, student, school) and the team points standings. Anyone can read a published
-- snapshot, without an account. Nothing else is copied here: ballots, judges' comments,
-- preliminary ranks and ratings, cumulative ranks, each judge's ranks, rating points and
-- tie-break details stay in the private tables, which visitors without an account cannot read.
-- Publishing again replaces the snapshot; unpublishing removes it.

create schema if not exists private;

-- When the director last published results. Null means not published.
alter table public.tournaments add column if not exists results_published_at timestamptz;

create table if not exists public.published_results (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  -- An event in a division: 'info' for varsity, 'info:novice' for novice (see contestKey in src/tournament.ts).
  contest text not null,
  event_id text not null check (char_length(event_id) between 1 and 40),
  division text not null default 'varsity' check (division in ('varsity', 'novice')),
  place int not null check (place between 1 and 20),
  student text not null check (char_length(btrim(student)) between 1 and 120),
  school text not null check (char_length(btrim(school)) between 1 and 120),
  constraint published_results_contest check (contest = case when division = 'novice' then event_id || ':novice' else event_id end)
);
create unique index if not exists published_results_one_per_student on public.published_results (tournament_id, contest, lower(school), lower(student));
create index if not exists published_results_by_school on public.published_results (lower(school));

create table if not exists public.published_team_points (
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  school text not null check (char_length(btrim(school)) between 1 and 120),
  points int not null check (points between 0 and 100000),
  place int not null check (place between 1 and 500)
);
create unique index if not exists published_team_points_one_per_school on public.published_team_points (tournament_id, lower(school));
create index if not exists published_team_points_by_school on public.published_team_points (lower(school));

-- Whether a tournament's results are public right now: it has ended and the director has published.
-- It lives in the public schema (not private) because visitors without an account call it from the
-- read policies below, and tournaments.sql revokes everything in the private schema from them.
create or replace function public.results_are_public(target uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tournaments t where t.id = target and t.status = 'finished' and t.results_published_at is not null);
$$;
revoke all on function public.results_are_public(uuid) from public;
grant execute on function public.results_are_public(uuid) to anon, authenticated;

-- The name, date and host of each tournament with published results, newest first. Visitors can't
-- read the tournaments table itself; this exposes only these columns, and only for published tournaments.
create or replace function public.published_tournaments()
returns table (id uuid, name text, date text, host text, published_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select t.id, t.name, t.date, t.host, t.results_published_at
  from public.tournaments t
  where t.status = 'finished' and t.results_published_at is not null
  order by t.results_published_at desc;
$$;
revoke all on function public.published_tournaments() from public;
grant execute on function public.published_tournaments() to anon, authenticated;

-- Results are withdrawn if the tournament is reopened (moved back from "finished"): the timestamp is
-- cleared before the change is saved, and the snapshot is removed after it. A new tournament never
-- starts out published.
create or replace function public.guard_published_results() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.results_published_at := null;
  elsif new.status <> 'finished' then
    new.results_published_at := null;
  end if;
  return new;
end;
$$;
drop trigger if exists guard_published_results on public.tournaments;
create trigger guard_published_results before insert or update on public.tournaments
  for each row execute function public.guard_published_results();

create or replace function public.withdraw_published_results() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.status = 'finished' and new.status <> 'finished' then
    delete from public.published_results where tournament_id = new.id;
    delete from public.published_team_points where tournament_id = new.id;
  end if;
  return null;
end;
$$;
drop trigger if exists withdraw_published_results on public.tournaments;
create trigger withdraw_published_results after update of status on public.tournaments
  for each row execute function public.withdraw_published_results();

revoke all on function public.guard_published_results() from public, anon, authenticated;
revoke all on function public.withdraw_published_results() from public, anon, authenticated;

-- Access rules. Anyone (with or without an account) reads published snapshots. Only the tournament's
-- director writes them, and only once the tournament has ended. Nobody edits a row in place: a new
-- snapshot replaces the old one.
alter table public.published_results enable row level security;
alter table public.published_team_points enable row level security;
revoke all on public.published_results, public.published_team_points from anon, authenticated;
grant select on public.published_results, public.published_team_points to anon;
grant select, insert, delete on public.published_results, public.published_team_points to authenticated;

drop policy if exists "Anyone reads published results" on public.published_results;
create policy "Anyone reads published results" on public.published_results for select to anon, authenticated
  using (public.results_are_public(tournament_id));
drop policy if exists "Directors read their own snapshot" on public.published_results;
create policy "Directors read their own snapshot" on public.published_results for select to authenticated
  using (private.is_director(tournament_id));
drop policy if exists "Directors publish results" on public.published_results;
create policy "Directors publish results" on public.published_results for insert to authenticated
  with check (private.is_director(tournament_id) and private.tournament_status(tournament_id) = 'finished');
drop policy if exists "Directors unpublish results" on public.published_results;
create policy "Directors unpublish results" on public.published_results for delete to authenticated
  using (private.is_director(tournament_id) and private.tournament_status(tournament_id) = 'finished');

drop policy if exists "Anyone reads published team points" on public.published_team_points;
create policy "Anyone reads published team points" on public.published_team_points for select to anon, authenticated
  using (public.results_are_public(tournament_id));
drop policy if exists "Directors read their own team points" on public.published_team_points;
create policy "Directors read their own team points" on public.published_team_points for select to authenticated
  using (private.is_director(tournament_id));
drop policy if exists "Directors publish team points" on public.published_team_points;
create policy "Directors publish team points" on public.published_team_points for insert to authenticated
  with check (private.is_director(tournament_id) and private.tournament_status(tournament_id) = 'finished');
drop policy if exists "Directors unpublish team points" on public.published_team_points;
create policy "Directors unpublish team points" on public.published_team_points for delete to authenticated
  using (private.is_director(tournament_id) and private.tournament_status(tournament_id) = 'finished');

-- Publish (or publish again): replace the snapshot and stamp the time, all at once.
-- Runs with the caller's rights, so the access rules above still decide what is allowed.
-- placings: [{ "contest", "event_id", "division", "place", "student", "school" }]
-- teams:    [{ "school", "points", "place" }]
create or replace function public.publish_results(target uuid, placings jsonb, teams jsonb) returns timestamptz
language plpgsql security invoker set search_path = '' as $$
declare
  stamped timestamptz := now();
begin
  if not private.is_director(target) then
    raise exception 'Only this tournament''s director can publish its results.' using errcode = 'insufficient_privilege';
  end if;
  if private.tournament_status(target) is distinct from 'finished' then
    raise exception 'Results can be published once the tournament has ended.' using errcode = 'check_violation';
  end if;
  if jsonb_typeof(placings) <> 'array' or jsonb_typeof(teams) <> 'array' then
    raise exception 'Placings and teams must be lists.' using errcode = 'invalid_parameter_value';
  end if;
  delete from public.published_results where tournament_id = target;
  delete from public.published_team_points where tournament_id = target;
  insert into public.published_results (tournament_id, contest, event_id, division, place, student, school)
    select target, x.contest, x.event_id, coalesce(x.division, 'varsity'), x.place, btrim(x.student), btrim(x.school)
    from jsonb_to_recordset(placings) as x (contest text, event_id text, division text, place int, student text, school text);
  insert into public.published_team_points (tournament_id, school, points, place)
    select target, btrim(x.school), x.points, x.place
    from jsonb_to_recordset(teams) as x (school text, points int, place int);
  update public.tournaments set results_published_at = stamped where id = target;
  return stamped;
end;
$$;

-- Unpublish: remove the snapshot. The tournament's private results are untouched.
create or replace function public.unpublish_results(target uuid) returns void
language plpgsql security invoker set search_path = '' as $$
begin
  if not private.is_director(target) then
    raise exception 'Only this tournament''s director can unpublish its results.' using errcode = 'insufficient_privilege';
  end if;
  delete from public.published_results where tournament_id = target;
  delete from public.published_team_points where tournament_id = target;
  update public.tournaments set results_published_at = null where id = target;
end;
$$;

revoke all on function public.publish_results(uuid, jsonb, jsonb) from public, anon;
revoke all on function public.unpublish_results(uuid) from public, anon;
grant execute on function public.publish_results(uuid, jsonb, jsonb) to authenticated;
grant execute on function public.unpublish_results(uuid) to authenticated;


-- ═════════ supabase/team_compare.sql ═════════
-- Orator: the team point scale behind published results, for Compare teams.
-- Run in the Supabase dashboard after public_results.sql: SQL Editor → New query → paste → Run.
-- Safe to run again.
--
-- published_team_points stores each school's total only. To show where a school earns its points
-- (team points by event), the app works them out from the published final placings and the scale the
-- tournament used: points for 1st to 6th (NSAA: 20-18-16-14-12-10) and whether novice finals counted.
-- The director's app sends that scale right after publish_results; it is public exactly when the
-- tournament's results are. Nothing private is added: no ballots, ranks, ratings or tie-breaks.

create table if not exists public.published_team_scoring (
  tournament_id uuid primary key references public.tournaments (id) on delete cascade,
  team_point_scale int[] not null default '{20,18,16,14,12,10}',
  novice_counts boolean not null default false,
  constraint published_team_scoring_scale check (
    cardinality(team_point_scale) between 1 and 20
    and array_position(team_point_scale, null) is null
    and 0 <= all (team_point_scale) and 1000 >= all (team_point_scale)
  )
);

-- Access rules: like the other published tables. Anyone reads it while the results are public; the
-- tournament's director writes it, once the tournament has ended.
alter table public.published_team_scoring enable row level security;
revoke all on public.published_team_scoring from anon, authenticated;
grant select on public.published_team_scoring to anon;
grant select, insert, delete on public.published_team_scoring to authenticated;

drop policy if exists "Anyone reads published team scoring" on public.published_team_scoring;
create policy "Anyone reads published team scoring" on public.published_team_scoring for select to anon, authenticated
  using (public.results_are_public(tournament_id));
drop policy if exists "Directors read their own team scoring" on public.published_team_scoring;
create policy "Directors read their own team scoring" on public.published_team_scoring for select to authenticated
  using (private.is_director(tournament_id));
drop policy if exists "Directors publish team scoring" on public.published_team_scoring;
create policy "Directors publish team scoring" on public.published_team_scoring for insert to authenticated
  with check (private.is_director(tournament_id) and private.tournament_status(tournament_id) = 'finished');
drop policy if exists "Directors unpublish team scoring" on public.published_team_scoring;
create policy "Directors unpublish team scoring" on public.published_team_scoring for delete to authenticated
  using (private.is_director(tournament_id) and private.tournament_status(tournament_id) = 'finished');

-- Save the scale with the published results. Called by the app straight after publish_results, so
-- the results must already be published. Runs with the caller's rights: the rules above still apply.
create or replace function public.publish_team_scoring(target uuid, scale int[], novice_counts boolean) returns void
language plpgsql security invoker set search_path = '' as $$
begin
  if not private.is_director(target) then
    raise exception 'Only this tournament''s director can publish its results.' using errcode = 'insufficient_privilege';
  end if;
  if private.tournament_status(target) is distinct from 'finished' then
    raise exception 'Results can be published once the tournament has ended.' using errcode = 'check_violation';
  end if;
  if not exists (select 1 from public.tournaments t where t.id = target and t.results_published_at is not null) then
    raise exception 'Publish the results first.' using errcode = 'check_violation';
  end if;
  delete from public.published_team_scoring where tournament_id = target;
  insert into public.published_team_scoring (tournament_id, team_point_scale, novice_counts)
    values (target, coalesce(scale, '{20,18,16,14,12,10}'), coalesce(novice_counts, false));
end;
$$;
revoke all on function public.publish_team_scoring(uuid, int[], boolean) from public, anon;
grant execute on function public.publish_team_scoring(uuid, int[], boolean) to authenticated;

-- Unpublishing or reopening the tournament (both clear results_published_at) removes the scale too,
-- so a later publish from an older app can't pick up a stale one.
create or replace function public.withdraw_team_scoring() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.results_published_at is not null and new.results_published_at is null then
    delete from public.published_team_scoring where tournament_id = new.id;
  end if;
  return null;
end;
$$;
revoke all on function public.withdraw_team_scoring() from public, anon, authenticated;
drop trigger if exists withdraw_team_scoring on public.tournaments;
create trigger withdraw_team_scoring after update of results_published_at, status on public.tournaments
  for each row execute function public.withdraw_team_scoring();


-- ═════════ supabase/semifinals.sql ═════════
-- Semifinals: an elimination round between the preliminary rounds and the final, for big fields.
-- Run after supabase/tournaments.sql. Safe to run again.
--
-- A semifinal room is a section with stage 'semi', held in the round after the last preliminary round.
-- Finals keep stage null (as before) and are told apart by their round: the round after prelims, or,
-- for a contest with semifinals, one round later. The director's semifinal plan for each contest is
-- saved in tournaments.settings (semisByContest), like the finals cut, so it needs no column.

alter table public.sections add column if not exists stage text;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'sections_stage_check') then
    alter table public.sections add constraint sections_stage_check check (stage is null or stage in ('prelim', 'semi', 'final'));
  end if;
end $$;

-- With five preliminary rounds, a semifinal is round 6 and its final round 7: allow up to 8.
alter table public.sections drop constraint if exists sections_round_check;
alter table public.sections add constraint sections_round_check check (round between 1 and 8);


-- ═════════ supabase/waitlist.sql ═════════
-- Entry caps and a waitlist. A director may cap entries per school and per event (each event and division
-- counted separately). An entry over a cap is still saved, but waitlisted: it isn't scheduled or charged
-- until the director admits it. Caps live in the tournament's settings (supabase/fixes.sql):
-- settings.schoolEntryCap and settings.eventEntryCap. Run after tournaments.sql and fixes.sql. Safe to run again.

alter table public.entries add column if not exists waitlisted boolean not null default false;

create or replace function public.waitlist_entry() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  t public.tournaments;
  school_cap int; event_cap int;
begin
  select * into t from public.tournaments where id = new.tournament_id;
  school_cap := nullif(t.settings->>'schoolEntryCap', '')::int;
  event_cap := nullif(t.settings->>'eventEntryCap', '')::int;
  -- The director's own late entries skip the waitlist.
  if private.is_director(new.tournament_id) then new.waitlisted := false; return new; end if;
  new.waitlisted := (school_cap is not null and (select count(*) from public.entries e where e.tournament_id = new.tournament_id and not e.waitlisted and lower(e.school) = lower(new.school)) >= school_cap)
    or (event_cap is not null and (select count(*) from public.entries e where e.tournament_id = new.tournament_id and not e.waitlisted and e.event_id = new.event_id and e.division = new.division) >= event_cap);
  return new;
end;
$$;
drop trigger if exists waitlist_entry on public.entries;
create trigger waitlist_entry before insert on public.entries for each row execute function public.waitlist_entry();
revoke all on function public.waitlist_entry() from public, anon, authenticated;

-- Only the director admits (or re-waitlists) an entry, and only that one field can change.
create or replace function public.guard_entry_update() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  -- Deleting a user account clears created_by on their entries (on delete set null). That runs with no one
  -- signed in; let it through, changing nothing else.
  if auth.uid() is null and new.created_by is null and old.created_by is not null and (to_jsonb(new) - 'created_by') = (to_jsonb(old) - 'created_by') then return new; end if;
  if not private.is_director(old.tournament_id) then raise exception 'Only the director can admit waitlisted entries.' using errcode = 'insufficient_privilege'; end if;
  new.id := old.id; new.tournament_id := old.tournament_id; new.school := old.school; new.student := old.student;
  new.event_id := old.event_id; new.division := old.division; new.created_by := old.created_by; new.created_at := old.created_at;
  return new;
end;
$$;
drop trigger if exists guard_entry_update on public.entries;
create trigger guard_entry_update before update on public.entries for each row execute function public.guard_entry_update();
revoke all on function public.guard_entry_update() from public, anon, authenticated;

grant update (waitlisted) on public.entries to authenticated;
drop policy if exists "Directors admit waitlisted entries" on public.entries;
create policy "Directors admit waitlisted entries" on public.entries for update to authenticated
  using (private.is_director(tournament_id)) with check (private.is_director(tournament_id));


-- ═════════ supabase/accessibility.sql ═════════
-- Room-accessibility requests. A coach marks that a student needs an accessible room (step-free, ground floor or
-- elevator), with an optional short note; it applies to all that student's entries. The director marks which rooms are
-- accessible in the tournament's settings (settings.accessibleRooms, saved like the room list; see fixes.sql), and the
-- schedule gives those students' rooms the accessible rooms first.
--
-- Privacy. The request and its note are kept OUT of public.entries on purpose: once the schedule is published every
-- approved member (judges, other schools' coaches and students) can read the whole field's entries ("Who can see
-- entries" in tournaments.sql), so even a yes/no column there would tell them which student asked. Instead requests live
-- in their own table, readable only by the director, the coach of that student's school, and the student themselves.
-- Judges and other coaches see at most that a room is accessible (from the room list), never who asked or why.
--
-- Who can change a request: the coach of that school while entries are open; the director anytime. No access column is
-- added to public.entries, so its update guard keeps exactly the waitlist.sql rules (only the director changes
-- `waitlisted`; every other column locked); it is replaced below only to let account deletion clean up `created_by`.
--
-- Run after waitlist.sql (and tournaments.sql, fixes.sql). Safe to run again.

create table if not exists public.access_requests (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  school text not null,
  student text not null,
  note text not null default '',
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  updated_at timestamptz not null default now()
);
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'access_requests_note_length') then
    alter table public.access_requests add constraint access_requests_note_length check (char_length(note) <= 200);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'access_requests_names') then
    alter table public.access_requests add constraint access_requests_names check (char_length(btrim(school)) between 1 and 120 and char_length(btrim(student)) between 1 and 120);
  end if;
end $$;
-- One request per student (name and school, any case) per tournament.
create unique index if not exists access_requests_one_per_student on public.access_requests (tournament_id, lower(btrim(school)), lower(btrim(student)));

-- True when the signed-in user is this student, approved at this tournament (matched like their ballots: school and roster name).
create or replace function private.is_access_student(target uuid, target_school text, target_student text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tournament_members m where m.tournament_id = target and m.user_id = (select auth.uid())
    and m.role = 'student' and m.status = 'approved' and lower(m.school) = lower(btrim(target_school)) and private.match_name(m) = lower(btrim(target_student)));
$$;
-- True when the signed-in user may change this school's requests now: the director anytime, the school's approved coach
-- while entries are open. Never a guest (anonymous judge-link) account.
create or replace function private.manages_access(target uuid, target_school text) returns boolean
language sql stable security definer set search_path = '' as $$
  select not coalesce((select u.is_anonymous from auth.users u where u.id = (select auth.uid())), false)
    and (private.is_director(target)
      or (private.entries_open(target) and lower(btrim(target_school)) = private.approved_coach_school(target)));
$$;
revoke all on function private.is_access_student(uuid, text, text) from public, anon;
revoke all on function private.manages_access(uuid, text) from public, anon;
grant usage on schema private to authenticated;
grant execute on function private.is_access_student(uuid, text, text) to authenticated;
grant execute on function private.manages_access(uuid, text) to authenticated;

-- A request can't move to another tournament, school or student; who changed it last is stamped.
create or replace function public.guard_access_request() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'UPDATE' then
    new.id := old.id; new.tournament_id := old.tournament_id; new.school := old.school; new.student := old.student;
  end if;
  new.note := btrim(coalesce(new.note, ''));
  new.updated_by := auth.uid(); new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists guard_access_request on public.access_requests;
create trigger guard_access_request before insert or update on public.access_requests for each row execute function public.guard_access_request();
revoke all on function public.guard_access_request() from public, anon, authenticated;

-- When a student's last entry is withdrawn, their request (and note) goes too.
create or replace function public.drop_orphan_access_request() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.access_requests r
  where r.tournament_id = old.tournament_id and lower(btrim(r.school)) = lower(btrim(old.school)) and lower(btrim(r.student)) = lower(btrim(old.student))
    and not exists (select 1 from public.entries e where e.tournament_id = old.tournament_id and lower(btrim(e.school)) = lower(btrim(old.school)) and lower(btrim(e.student)) = lower(btrim(old.student)));
  return old;
end;
$$;
drop trigger if exists drop_orphan_access_request on public.entries;
create trigger drop_orphan_access_request after delete on public.entries for each row execute function public.drop_orphan_access_request();
revoke all on function public.drop_orphan_access_request() from public, anon, authenticated;

alter table public.access_requests enable row level security;
revoke all on public.access_requests from anon, authenticated;
grant select, insert, update, delete on public.access_requests to authenticated;

drop policy if exists "Who can see accessibility requests" on public.access_requests;
create policy "Who can see accessibility requests" on public.access_requests for select to authenticated
  using (private.is_director(tournament_id)
    or lower(btrim(school)) = (select private.approved_coach_school(tournament_id))
    or private.is_access_student(tournament_id, school, student));
drop policy if exists "Coaches and the director add requests" on public.access_requests;
create policy "Coaches and the director add requests" on public.access_requests for insert to authenticated
  with check (private.manages_access(tournament_id, school));
drop policy if exists "Coaches and the director change requests" on public.access_requests;
create policy "Coaches and the director change requests" on public.access_requests for update to authenticated
  using (private.manages_access(tournament_id, school)) with check (private.manages_access(tournament_id, school));
drop policy if exists "Coaches and the director remove requests" on public.access_requests;
create policy "Coaches and the director remove requests" on public.access_requests for delete to authenticated
  using (private.manages_access(tournament_id, school));
-- (An earlier draft had a separate guest policy; guests are now refused in private.manages_access.)
drop policy if exists "Guests cannot add requests" on public.access_requests;

-- Add, change or remove one student's request. Runs with the caller's rights, so the policies above decide who may.
create or replace function public.set_access_request(target uuid, target_school text, target_student text, needed boolean, note text default '')
returns void language plpgsql security invoker set search_path = '' as $$
begin
  if not private.manages_access(target, target_school) then
    raise exception 'Only the director, or this school''s coach while entries are open, can change an accessibility request.' using errcode = 'insufficient_privilege';
  end if;
  if needed then
    insert into public.access_requests as r (tournament_id, school, student, note)
    values (target, btrim(target_school), btrim(target_student), btrim(coalesce(note, '')))
    on conflict (tournament_id, lower(btrim(school)), lower(btrim(student))) do update set note = excluded.note;
  else
    delete from public.access_requests r where r.tournament_id = target
      and lower(btrim(r.school)) = lower(btrim(target_school)) and lower(btrim(r.student)) = lower(btrim(target_student));
  end if;
end;
$$;
revoke all on function public.set_access_request(uuid, text, text, boolean, text) from public, anon;
grant execute on function public.set_access_request(uuid, text, text, boolean, text) to authenticated;

-- ── public.entries update guard, replacing waitlist.sql's version with every rule kept: only the director may update an
-- entry, and only `waitlisted` can change (every other column is put back). One addition: deleting an account runs the
-- `created_by ... on delete set null` foreign key as an UPDATE with nobody signed in; that system cleanup (auth.uid() is
-- null and the only change is created_by becoming null) is let through unchanged, so deleting a user who entered students works.
create or replace function public.guard_entry_update() returns trigger
language plpgsql security definer set search_path = '' as $$
declare unchanged public.entries;
begin
  if auth.uid() is null and old.created_by is not null and new.created_by is null then
    unchanged := new; unchanged.created_by := old.created_by;
    if unchanged is not distinct from old then return new; end if;
  end if;
  if not private.is_director(old.tournament_id) then raise exception 'Only the director can admit waitlisted entries.' using errcode = 'insufficient_privilege'; end if;
  new.id := old.id; new.tournament_id := old.tournament_id; new.school := old.school; new.student := old.student;
  new.event_id := old.event_id; new.division := old.division; new.created_by := old.created_by; new.created_at := old.created_at;
  return new;
end;
$$;
drop trigger if exists guard_entry_update on public.entries;
create trigger guard_entry_update before update on public.entries for each row execute function public.guard_entry_update();
revoke all on function public.guard_entry_update() from public, anon, authenticated;


-- ═════════ supabase/judges.sql ═════════
-- Orator: coach-entered judges and private judge sign-in links.
-- Run in the Supabase SQL Editor after schema.sql, ballots.sql, tournaments.sql, fixes.sql, calendar.sql
-- and public_results.sql. Safe to run again.
--
-- SUPABASE SETTING NEEDED: Authentication → Sign In / Providers → turn on "Allow anonymous sign-ins".
-- (Keep "Confirm email" as it is.) Without it a judge link shows "Guest judge sign-in is turned off".
--
-- How it works
-- • An approved coach enters their school's judges for a tournament (name, optional email and phone,
--   clean judge or the schools they know). A coach-entered judge is APPROVED AT ONCE: the coach was
--   approved by the director and answers for their own judges. The director can decline or remove any
--   of them, and they then drop out of the judge pool.
-- • Each judge gets a private sign-in link. The link holds a random 32-byte token; only its SHA-256
--   hash is stored, so nobody (not the coach, not the director) can read a link back. Making a new
--   link replaces the old one, which stops working at once.
-- • Opening the link signs the judge in as a Supabase anonymous user and calls claim_judge_link(),
--   which binds that user to the judge's seat: an approved judge row in tournament_members with the
--   coach-entered name and school. They then see only their own rooms and fill in those ballots
--   (sections.judge_id = auth.uid(), checked by check_ballot_room from tournaments.sql).
-- • Opening the same link on another device moves the seat there (a judge who switches phones keeps
--   going). The ballots already started or submitted move with the seat; the old device loses it.
--   Turning the link off (revoke) stops it working and signs whoever holds the seat out of it: their
--   unsubmitted drafts are discarded, submitted ballots are kept. A new link can then be made.
-- • A judge who prefers an account can still sign up and ask to join as before. If such an account
--   matches a coach-entered judge, the director can merge them (merge_judge_seat): the account takes
--   the seat and the duplicate disappears from the pool. Otherwise both are shown, flagged.
-- • Anonymous users can only claim a seat: they cannot create tournaments, ask to join, enter students,
--   set practice goals, enter judges, or start a ballot without holding a seat.

create schema if not exists private;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

-- ── Tables ──────────────────────────────────────────────────────────────────────────────────────
create table if not exists public.coach_judges (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  school text not null default '',
  name text not null check (char_length(btrim(name)) between 1 and 80),
  email text not null default '' check (char_length(email) <= 200),
  phone text not null default '' check (char_length(phone) <= 40),
  clean_judge boolean not null default false,
  known_schools text[] not null default '{}',
  status text not null default 'approved' check (status in ('approved', 'declined')),
  token_hash text unique,                       -- sha256 of the link token, hex. Never readable by users.
  link_created_at timestamptz,
  revoked_at timestamptz,
  claimed_by uuid references auth.users (id) on delete set null,
  claimed_at timestamptz,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists coach_judges_by_school on public.coach_judges (tournament_id, lower(school));
-- One seat per account per tournament.
create unique index if not exists coach_judges_one_seat_each on public.coach_judges (tournament_id, claimed_by) where claimed_by is not null;

-- The judge row a seat's holder has, and the seat a room is assigned to (kept while nobody holds it).
alter table public.tournament_members add column if not exists coach_judge_id uuid references public.coach_judges (id) on delete cascade;
create unique index if not exists tournament_members_one_row_per_seat on public.tournament_members (coach_judge_id) where coach_judge_id is not null;
alter table public.sections add column if not exists coach_judge_id uuid references public.coach_judges (id) on delete set null;

-- ── Helpers ─────────────────────────────────────────────────────────────────────────────────────
create or replace function private.is_anonymous() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select u.is_anonymous from auth.users u where u.id = (select auth.uid())), false);
$$;

-- The tournament's director, or the coach approved for that school at that tournament.
create or replace function private.manages_judges(target uuid, target_school text) returns boolean
language sql stable security definer set search_path = '' as $$
  select private.is_director(target)
    or (not private.is_anonymous() and coalesce(lower(btrim(target_school)) = private.approved_coach_school(target), false));
$$;

create or replace function private.holds_judge_seat() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.coach_judges c where c.claimed_by = (select auth.uid()) and c.status = 'approved');
$$;

create or replace function private.judge_token_hash(token text) returns text
language sql immutable set search_path = '' as $$
  select encode(sha256(convert_to(coalesce(token, ''), 'UTF8')), 'hex');
$$;

revoke all on function private.is_anonymous() from public, anon;
revoke all on function private.manages_judges(uuid, text) from public, anon;
revoke all on function private.holds_judge_seat() from public, anon;
revoke all on function private.judge_token_hash(text) from public, anon, authenticated;
grant usage on schema private to authenticated;
grant execute on function private.is_anonymous() to authenticated;
grant execute on function private.manages_judges(uuid, text) to authenticated;
grant execute on function private.holds_judge_seat() to authenticated;

-- ── Anonymous (guest judge) accounts ──────────────────────────────────────────────────────────
-- Whatever a guest sends at sign-in, their profile is a judge with no school: they can never
-- pose as a coach (coach roles read their school's ballots) or a director.
create or replace function public.limit_guest_profile() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if coalesce((select u.is_anonymous from auth.users u where u.id = new.id), false) then
    new.roles := array['judge']; new.school := '';
  end if;
  return new;
end;
$$;
drop trigger if exists limit_guest_profile on public.profiles;
create trigger limit_guest_profile before insert on public.profiles for each row execute function public.limit_guest_profile();
revoke all on function public.limit_guest_profile() from public, anon, authenticated;

-- Restrictive policies: these apply on top of every other policy on the table.
drop policy if exists "Guests cannot create tournaments" on public.tournaments;
create policy "Guests cannot create tournaments" on public.tournaments as restrictive for insert to authenticated with check (not private.is_anonymous());
drop policy if exists "Guests join only through a judge link" on public.tournament_members;
create policy "Guests join only through a judge link" on public.tournament_members as restrictive for insert to authenticated with check (not private.is_anonymous());
drop policy if exists "Guests cannot enter students" on public.entries;
create policy "Guests cannot enter students" on public.entries as restrictive for insert to authenticated with check (not private.is_anonymous());
drop policy if exists "Guests cannot set goals" on public.practice_goals;
create policy "Guests cannot set goals" on public.practice_goals as restrictive for insert to authenticated with check (not private.is_anonymous());
drop policy if exists "Guests start ballots only with a seat" on public.ballots;
create policy "Guests start ballots only with a seat" on public.ballots as restrictive for insert to authenticated
  with check (not private.is_anonymous() or private.holds_judge_seat());

-- ── Coach-entered judges: who may do what ───────────────────────────────────────────────────
create or replace function public.guard_coach_judge() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if coalesce(private.tournament_status(new.tournament_id), 'finished') = 'finished' then
      raise exception 'This tournament has ended.' using errcode = 'check_violation';
    end if;
    new.school := btrim(new.school);
    new.status := 'approved';             -- approved at once: the coach is approved; the director can decline
    new.token_hash := null; new.link_created_at := null; new.revoked_at := null; new.claimed_by := null; new.claimed_at := null;
    new.created_by := auth.uid(); new.created_at := now();
  else
    new.id := old.id; new.tournament_id := old.tournament_id; new.school := old.school;
    new.created_by := old.created_by; new.created_at := old.created_at;
    -- Only the director decides; a coach removes a judge by deleting them.
    if auth.uid() is not null and not private.is_director(old.tournament_id) then new.status := old.status; end if;
  end if;
  new.name := btrim(new.name); new.email := btrim(new.email); new.phone := btrim(new.phone);
  select coalesce(array_agg(distinct btrim(s)), '{}') into new.known_schools from unnest(new.known_schools) s where btrim(s) <> '';
  if new.clean_judge then new.known_schools := '{}'; end if;
  return new;
end;
$$;
drop trigger if exists guard_coach_judge on public.coach_judges;
create trigger guard_coach_judge before insert or update on public.coach_judges for each row execute function public.guard_coach_judge();

-- Keep the holder's judge row in step with the seat (name, school, conflicts, the director's decision).
create or replace function public.sync_coach_judge() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  -- A change that came from the judge row itself (the judge editing their conflicts) is already there.
  if pg_trigger_depth() > 1 then return null; end if;
  update public.tournament_members m set coach_judge_id = m.coach_judge_id where m.coach_judge_id = new.id and m.user_id = new.claimed_by;
  return null;
end;
$$;
drop trigger if exists sync_coach_judge on public.coach_judges;
create trigger sync_coach_judge after update on public.coach_judges for each row execute function public.sync_coach_judge();

-- Removing a judge: their rooms go back to unassigned, and a guest holder's drafts are discarded.
-- (Their judge row goes with the seat: tournament_members.coach_judge_id cascades.)
create or replace function public.release_coach_judge() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update public.sections s set judge_id = null, judge_name = '', coach_judge_id = null where s.coach_judge_id = old.id;
  if old.claimed_by is not null then
    update public.sections s set judge_id = null, judge_name = '' where s.tournament_id = old.tournament_id and s.judge_id = old.claimed_by;
    if coalesce((select u.is_anonymous from auth.users u where u.id = old.claimed_by), false) then
      delete from public.ballots b where b.judge_id = old.claimed_by and b.tournament_id = old.tournament_id and b.status = 'draft';
    end if;
  end if;
  return old;
end;
$$;
drop trigger if exists release_coach_judge on public.coach_judges;
create trigger release_coach_judge before delete on public.coach_judges for each row execute function public.release_coach_judge();

revoke all on function public.guard_coach_judge() from public, anon, authenticated;
revoke all on function public.sync_coach_judge() from public, anon, authenticated;
revoke all on function public.release_coach_judge() from public, anon, authenticated;

alter table public.coach_judges enable row level security;
revoke all on public.coach_judges from anon, authenticated;
-- No token_hash and no claimed_by: a link can't be read back, and the holder's account stays private.
grant select (id, tournament_id, school, name, email, phone, clean_judge, known_schools, status, link_created_at, revoked_at, claimed_at, created_at) on public.coach_judges to authenticated;
grant insert (id, tournament_id, school, name, email, phone, clean_judge, known_schools) on public.coach_judges to authenticated;
grant update (name, email, phone, clean_judge, known_schools, status) on public.coach_judges to authenticated;
grant delete on public.coach_judges to authenticated;

drop policy if exists "Coach and director see entered judges" on public.coach_judges;
create policy "Coach and director see entered judges" on public.coach_judges for select to authenticated
  using (private.manages_judges(tournament_id, school));
drop policy if exists "Coaches enter their own school's judges" on public.coach_judges;
create policy "Coaches enter their own school's judges" on public.coach_judges for insert to authenticated
  with check (private.manages_judges(tournament_id, school));
drop policy if exists "Coach and director edit entered judges" on public.coach_judges;
create policy "Coach and director edit entered judges" on public.coach_judges for update to authenticated
  using (private.manages_judges(tournament_id, school)) with check (private.manages_judges(tournament_id, school));
drop policy if exists "Coach and director remove entered judges" on public.coach_judges;
create policy "Coach and director remove entered judges" on public.coach_judges for delete to authenticated
  using (private.manages_judges(tournament_id, school));

-- ── The holder's judge row ──────────────────────────────────────────────────────────────────────
-- Runs after stamp_member, guard_check_in and guard_roster_name (triggers fire in name order).
-- A row may point at a seat only if its user holds that seat; the row then mirrors the seat.
create or replace function public.zz_coach_judge_member() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  cj public.coach_judges;
begin
  if new.coach_judge_id is null then
    if tg_op = 'UPDATE' and old.coach_judge_id is not null
       and exists (select 1 from public.coach_judges c where c.id = old.coach_judge_id and c.claimed_by = old.user_id) then
      new.coach_judge_id := old.coach_judge_id;   -- only leaving the seat (see unbind_judge_seat) clears it
    else
      return new;
    end if;
  end if;
  select * into cj from public.coach_judges c where c.id = new.coach_judge_id;
  if cj.id is null or cj.claimed_by is distinct from new.user_id or cj.tournament_id <> new.tournament_id or new.role <> 'judge' then
    raise exception 'That judge seat belongs to someone else.' using errcode = 'insufficient_privilege';
  end if;
  new.display_name := cj.name;
  new.school := cj.school;
  new.status := case when cj.status = 'approved' then 'approved' else 'declined' end;
  if tg_op = 'UPDATE' and (new.clean_judge is distinct from old.clean_judge or new.known_schools is distinct from old.known_schools)
     and (new.clean_judge is distinct from cj.clean_judge or new.known_schools is distinct from cj.known_schools) then
    -- The judge corrected their own conflicts: the coach sees the change too.
    update public.coach_judges c set clean_judge = new.clean_judge, known_schools = new.known_schools where c.id = cj.id;
    if new.clean_judge then new.known_schools := '{}'; end if;
  else
    new.clean_judge := cj.clean_judge; new.known_schools := cj.known_schools;
  end if;
  return new;
end;
$$;
drop trigger if exists zz_coach_judge_member on public.tournament_members;
create trigger zz_coach_judge_member before insert or update on public.tournament_members for each row execute function public.zz_coach_judge_member();
revoke all on function public.zz_coach_judge_member() from public, anon, authenticated;

-- ── Rooms assigned to a seat ────────────────────────────────────────────────────────────────────
-- The app assigns an unclaimed coach-entered judge by coach_judge_id; the room's judge_id follows
-- whoever holds the seat, so check_ballot_room keeps working unchanged.
create or replace function public.zz_coach_judge_section() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  holder uuid;
begin
  if tg_op = 'INSERT' or new.coach_judge_id is distinct from old.coach_judge_id then
    if new.coach_judge_id is not null then
      select c.claimed_by into holder from public.coach_judges c where c.id = new.coach_judge_id and c.tournament_id = new.tournament_id and c.status = 'approved';
      if not found then raise exception 'That judge is not entered at this tournament.' using errcode = 'check_violation'; end if;
      new.judge_id := holder;
      return new;
    end if;
  elsif new.judge_id is not distinct from old.judge_id then
    return new;
  elsif new.judge_id is null and exists (select 1 from public.coach_judges c where c.id = old.coach_judge_id and c.claimed_by is null) then
    return new;   -- the seat's holder signed out: the room stays with the seat
  end if;
  new.coach_judge_id := (select c.id from public.coach_judges c where new.judge_id is not null and c.tournament_id = new.tournament_id and c.claimed_by = new.judge_id);
  return new;
end;
$$;
drop trigger if exists zz_coach_judge_section on public.sections;
create trigger zz_coach_judge_section before insert or update on public.sections for each row execute function public.zz_coach_judge_section();
revoke all on function public.zz_coach_judge_section() from public, anon, authenticated;

-- ── Binding a seat to an account ────────────────────────────────────────────────────────────────
-- The previous holder leaves: a guest's judge row is removed (an account's is kept, unlinked), and
-- their rooms stay with the seat. With `discard_drafts`, a guest holder's unsubmitted drafts go too.
create or replace function private.unbind_judge_seat(seat uuid, discard_drafts boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare
  cj public.coach_judges;
  guest boolean;
begin
  select * into cj from public.coach_judges c where c.id = seat for update;
  if cj.id is null then return; end if;
  -- Defence in depth (private functions aren't reachable through the API): a manager, or a claim in progress.
  if not (private.manages_judges(cj.tournament_id, cj.school) or current_setting('orator.claiming', true) = seat::text) then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  if cj.claimed_by is null then return; end if;
  guest := coalesce((select u.is_anonymous from auth.users u where u.id = cj.claimed_by), false);
  update public.coach_judges c set claimed_by = null, claimed_at = null where c.id = seat;
  update public.sections s set judge_id = null where s.coach_judge_id = seat;
  if guest then
    delete from public.tournament_members m where m.coach_judge_id = seat;
    if discard_drafts then delete from public.ballots b where b.judge_id = cj.claimed_by and b.tournament_id = cj.tournament_id and b.status = 'draft'; end if;
  else
    update public.tournament_members m set coach_judge_id = null where m.coach_judge_id = seat;
  end if;
end;
$$;

-- `holder` takes the seat. With `move_ballots` (only when holder is the caller, i.e. a claim), the
-- previous holder's ballots for this tournament are copied to the holder and removed from the old account.
create or replace function private.bind_judge_seat(seat uuid, holder uuid, move_ballots boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare
  cj public.coach_judges;
  previous uuid;
  b public.ballots;
  copy uuid;
begin
  select * into cj from public.coach_judges c where c.id = seat for update;
  if cj.id is null or not (private.is_director(cj.tournament_id) or (holder = auth.uid() and current_setting('orator.claiming', true) = seat::text)) then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  previous := cj.claimed_by;
  if previous is not distinct from holder then return; end if;
  if previous is not null then
    perform private.unbind_judge_seat(seat, false);
  end if;
  update public.coach_judges c set claimed_by = holder, claimed_at = now() where c.id = seat;
  if exists (select 1 from public.tournament_members m where m.tournament_id = cj.tournament_id and m.user_id = holder and m.role = 'judge') then
    update public.tournament_members m set coach_judge_id = seat where m.tournament_id = cj.tournament_id and m.user_id = holder and m.role = 'judge';
  else
    -- stamp_member makes the row the caller's own; only a claim gets here (holder = caller).
    insert into public.tournament_members (tournament_id, role, school, coach_judge_id) values (cj.tournament_id, 'judge', cj.school, seat);
  end if;
  -- Rooms follow the seat (zz_coach_judge_section links them back to it).
  update public.sections s set judge_id = holder where s.coach_judge_id = seat;
  if previous is not null then
    update public.sections s set judge_id = holder, coach_judge_id = seat where s.tournament_id = cj.tournament_id and s.judge_id = previous;
  end if;
  if move_ballots and previous is not null and holder = auth.uid() then
    for b in select * from public.ballots x where x.judge_id = previous and x.tournament_id = cj.tournament_id order by x.created_at loop
      begin
        copy := null;
        -- stamp_ballot stamps the caller as the judge.
        insert into public.ballots (tournament, round, room, event_id, class_a, tournament_id, section_id)
          values (b.tournament, b.round, b.room, b.event_id, b.class_a, b.tournament_id, b.section_id)
          on conflict do nothing returning id into copy;
        if copy is not null then
          insert into public.ballot_entries (ballot_id, speaker_code, speaker_name, school, present, rank, rating, time_seconds, time_penalty, section_marks, reason, disqualifications, comments)
            select copy, e.speaker_code, e.speaker_name, e.school, e.present, e.rank, e.rating, e.time_seconds, e.time_penalty, e.section_marks, e.reason, e.disqualifications, e.comments
            from public.ballot_entries e where e.ballot_id = b.id;
          insert into public.ballot_private_notes (ballot_id, speaker_code, note) select copy, n.speaker_code, n.note from public.ballot_private_notes n where n.ballot_id = b.id;
          if b.status = 'submitted' then update public.ballots x set status = 'submitted' where x.id = copy; end if;
          delete from public.ballots x where x.id = b.id;
        end if;
      exception when others then
        null;   -- a ballot that can't move (e.g. its room was reassigned) stays where it was
      end;
    end loop;
  end if;
end;
$$;
revoke all on function private.unbind_judge_seat(uuid, boolean) from public, anon, authenticated;
revoke all on function private.bind_judge_seat(uuid, uuid, boolean) from public, anon, authenticated;

-- ── The functions the app calls ─────────────────────────────────────────────────────────────────
-- A coach (or the director) makes a new sign-in link for one judge. The token is returned once and
-- only its hash is kept; any earlier link for this judge stops working. The current holder keeps the seat.
create or replace function public.create_judge_link(seat uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare
  cj public.coach_judges;
  token text;
begin
  select * into cj from public.coach_judges c where c.id = seat;
  if cj.id is null or not private.manages_judges(cj.tournament_id, cj.school) then
    raise exception 'Only this judge''s coach or the tournament director can make their link.' using errcode = 'insufficient_privilege';
  end if;
  if cj.status <> 'approved' then raise exception 'The director has declined this judge.' using errcode = 'check_violation'; end if;
  token := rtrim(translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/', '-_'), '=');
  update public.coach_judges c set token_hash = private.judge_token_hash(token), link_created_at = now(), revoked_at = null where c.id = seat;
  return token;
end;
$$;

-- Turn a link off: it stops working, and whoever holds the seat is signed out of it.
create or replace function public.revoke_judge_link(seat uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  cj public.coach_judges;
begin
  select * into cj from public.coach_judges c where c.id = seat;
  if cj.id is null or not private.manages_judges(cj.tournament_id, cj.school) then
    raise exception 'Only this judge''s coach or the tournament director can turn off their link.' using errcode = 'insufficient_privilege';
  end if;
  update public.coach_judges c set token_hash = null, revoked_at = now() where c.id = seat;
  perform private.unbind_judge_seat(seat, true);
end;
$$;

-- A judge opens their link. Any signed-in user may call this (in the app: a fresh anonymous user).
-- Returns the seat they now hold. Calling it again from the same account changes nothing.
create or replace function public.claim_judge_link(token text)
returns table (tournament_id uuid, seat_id uuid, judge_name text, school text, tournament_name text)
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare
  me uuid := auth.uid();
  cj public.coach_judges;
begin
  if me is null then raise exception 'Sign in first.' using errcode = 'insufficient_privilege'; end if;
  if token is null or char_length(token) < 32 or char_length(token) > 200 then
    raise exception 'This judge link isn''t valid. Ask your coach to send it again.' using errcode = 'check_violation';
  end if;
  select * into cj from public.coach_judges c where c.token_hash = private.judge_token_hash(token) and c.revoked_at is null for update;
  if cj.id is null then
    raise exception 'This judge link isn''t valid any more. It may have been replaced or turned off. Ask your coach for a new one.' using errcode = 'check_violation';
  end if;
  if cj.status <> 'approved' then
    raise exception 'The tournament director has removed this judge. Talk to the director if that''s a mistake.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.coach_judges c where c.tournament_id = cj.tournament_id and c.claimed_by = me and c.id <> cj.id) then
    raise exception 'This device is already signed in as another judge at this tournament. Sign out first, then open the link again.' using errcode = 'check_violation';
  end if;
  if cj.claimed_by is distinct from me then
    -- A guest becomes this judge; an account keeps its own name and gains the judge role.
    update public.profiles p set
      roles = case when private.is_anonymous() then array['judge'] when 'judge' = any (p.roles) then p.roles else p.roles || array['judge'] end,
      full_name = case when private.is_anonymous() or btrim(p.full_name) = '' then cj.name else p.full_name end
    where p.id = me;
    if not found then
      insert into public.profiles (id, full_name, school, roles) values (me, cj.name, '', array['judge']);
    end if;
    perform set_config('orator.claiming', cj.id::text, true);
    perform private.bind_judge_seat(cj.id, me, true);
    perform set_config('orator.claiming', '', true);
  end if;
  return query select cj.tournament_id, cj.id, cj.name, cj.school, t.name from public.tournaments t where t.id = cj.tournament_id;
end;
$$;

-- The director merges a coach-entered judge with a judge who joined with their own account
-- (same person): the account takes the seat. Ballots a guest device already started stay with it.
create or replace function public.merge_judge_seat(seat uuid, account uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  cj public.coach_judges;
begin
  select * into cj from public.coach_judges c where c.id = seat;
  if cj.id is null or not private.is_director(cj.tournament_id) then
    raise exception 'Only the tournament director can merge judges.' using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from public.tournament_members m where m.tournament_id = cj.tournament_id and m.user_id = account and m.role = 'judge' and m.coach_judge_id is null) then
    raise exception 'That account hasn''t joined this tournament as a judge.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.coach_judges c where c.tournament_id = cj.tournament_id and c.claimed_by = account) then
    raise exception 'That account already holds a judge seat.' using errcode = 'check_violation';
  end if;
  perform private.bind_judge_seat(seat, account, false);
end;
$$;

revoke all on function public.create_judge_link(uuid) from public, anon;
revoke all on function public.revoke_judge_link(uuid) from public, anon;
revoke all on function public.claim_judge_link(text) from public, anon;
revoke all on function public.merge_judge_seat(uuid, uuid) from public, anon;
grant execute on function public.create_judge_link(uuid) to authenticated;
grant execute on function public.revoke_judge_link(uuid) to authenticated;
grant execute on function public.claim_judge_link(text) to authenticated;
grant execute on function public.merge_judge_seat(uuid, uuid) to authenticated;


-- ═════════ supabase/drops.sql ═════════
-- Drop deadlines and drop fees. Run after judges.sql (and before paper_ballots.sql and alerts.sql). Safe to run again.
--
-- The director sets, in the tournament's settings (supabase/fixes.sql):
--   settings.dropDeadline    an ISO date and time ("2026-11-14T23:59:00.000Z"); none means drops are never charged
--   settings.dropEntryFee    dollars per entry dropped after the deadline (default 0)
--   settings.dropJudgeFee    dollars per coach-entered judge dropped after the deadline (default 0)
--   settings.freezeEntryFees true: an entry dropped after the deadline still owes its entry fee (settings.fees.entry, default 7)
--
-- When a coach deletes one of their entries (public.entries) or judges (public.coach_judges) after the deadline,
-- an AFTER DELETE trigger records a drop in public.entry_drops with the fees as they stand at that moment, so
-- changing the fees later never changes earlier drops. Nothing is recorded:
--   * before the deadline, or when there is no deadline;
--   * for a waitlisted entry (it was never charged), or a judge the director had declined;
--   * when the director removes it: the director's own removals are never charged (a director removes an entry
--     to correct a mistake or on a coach's behalf, which isn't the school dropping late);
--   * when nobody is signed in (the SQL Editor or the service role), or the whole tournament is being deleted.
-- A student dropped and re-added in the same event is still a drop; the director can waive it.
--
-- Access: the director reads every drop at their tournament and waives or restores one (with a reason); an
-- approved coach reads their own school's drops; nobody else reads them. Nobody inserts, deletes or edits
-- drops directly: only the triggers write them, and the director may change only waived and waive_reason.

create schema if not exists private;

create table if not exists public.entry_drops (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  school text not null default '',
  kind text not null check (kind in ('entry', 'judge')),
  name text not null default '',
  event_id text,                                   -- entries only
  division text check (division is null or division in ('varsity', 'novice')),
  dropped_at timestamptz not null default now(),
  dropped_by uuid references auth.users (id) on delete set null,
  dropped_by_name text not null default '',
  fee numeric(10, 2) not null default 0 check (fee >= 0),            -- the drop fee
  entry_fee numeric(10, 2) not null default 0 check (entry_fee >= 0), -- the frozen entry fee, 0 unless fees froze
  waived boolean not null default false,
  waive_reason text not null default '' check (char_length(waive_reason) <= 200),
  waived_at timestamptz,
  waived_by uuid references auth.users (id) on delete set null
);
create index if not exists entry_drops_by_school on public.entry_drops (tournament_id, lower(school));

-- ── Reading the settings safely: a malformed value counts as no deadline, or $0. ───────────────────
create or replace function private.drop_deadline(settings jsonb) returns timestamptz
language plpgsql stable set search_path = '' as $$
begin
  return nullif(btrim(settings->>'dropDeadline'), '')::timestamptz;
exception when others then return null;
end;
$$;

create or replace function private.drop_amount(value text, fallback numeric) returns numeric
language plpgsql immutable set search_path = '' as $$
begin
  return greatest(0, round(coalesce(nullif(btrim(value), '')::numeric, fallback), 2));
exception when others then return fallback;
end;
$$;

-- Records a coach's drop if the tournament's deadline has passed. Returns quietly otherwise.
create or replace function private.record_drop(target uuid, drop_kind text, drop_school text, drop_name text, drop_event text, drop_division text) returns void
language plpgsql security definer set search_path = '' as $$
declare
  t public.tournaments;
  who uuid := auth.uid();
  deadline timestamptz;
  drop_fee numeric; frozen numeric := 0;
begin
  if who is null then return; end if;
  select * into t from public.tournaments where id = target;
  if not found then return; end if;                       -- the tournament itself is being deleted
  if t.director_id = who then return; end if;             -- the director's removals are never charged
  deadline := private.drop_deadline(t.settings);
  if deadline is null or now() <= deadline then return; end if;
  drop_fee := private.drop_amount(t.settings->>(case when drop_kind = 'entry' then 'dropEntryFee' else 'dropJudgeFee' end), 0);
  if drop_kind = 'entry' and coalesce(t.settings->'freezeEntryFees' = 'true'::jsonb, false) then
    frozen := private.drop_amount(t.settings->'fees'->>'entry', 7);
  end if;
  insert into public.entry_drops (tournament_id, school, kind, name, event_id, division, dropped_by, dropped_by_name, fee, entry_fee)
  values (target, drop_school, drop_kind, drop_name, drop_event, drop_division, who,
    coalesce((select nullif(btrim(p.full_name), '') from public.profiles p where p.id = who), 'Coach'), drop_fee, frozen);
end;
$$;

create or replace function public.record_entry_drop() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not coalesce(old.waitlisted, false) then
    perform private.record_drop(old.tournament_id, 'entry', old.school, old.student, old.event_id, old.division);
  end if;
  return null;
end;
$$;
drop trigger if exists record_entry_drop on public.entries;
create trigger record_entry_drop after delete on public.entries for each row execute function public.record_entry_drop();

create or replace function public.record_judge_drop() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.status = 'approved' then
    perform private.record_drop(old.tournament_id, 'judge', old.school, old.name, null, null);
  end if;
  return null;
end;
$$;
drop trigger if exists record_judge_drop on public.coach_judges;
create trigger record_judge_drop after delete on public.coach_judges for each row execute function public.record_judge_drop();

-- The director may only waive or restore: every other column keeps its value, and who waived it and when is stamped.
create or replace function public.guard_entry_drop() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not private.is_director(old.tournament_id) then
    raise exception 'Only the tournament director can waive a drop fee.' using errcode = 'insufficient_privilege';
  end if;
  new.id := old.id; new.tournament_id := old.tournament_id; new.school := old.school; new.kind := old.kind; new.name := old.name;
  new.event_id := old.event_id; new.division := old.division; new.dropped_at := old.dropped_at; new.dropped_by := old.dropped_by;
  new.dropped_by_name := old.dropped_by_name; new.fee := old.fee; new.entry_fee := old.entry_fee;
  new.waive_reason := btrim(coalesce(new.waive_reason, ''));
  if new.waived then
    if new.waive_reason = '' then raise exception 'Give a reason for waiving this drop fee.' using errcode = 'check_violation'; end if;
    if not old.waived or new.waive_reason is distinct from old.waive_reason then new.waived_at := now(); new.waived_by := auth.uid(); else new.waived_at := old.waived_at; new.waived_by := old.waived_by; end if;
  else
    new.waive_reason := ''; new.waived_at := null; new.waived_by := null;
  end if;
  return new;
end;
$$;
drop trigger if exists guard_entry_drop on public.entry_drops;
create trigger guard_entry_drop before update on public.entry_drops for each row execute function public.guard_entry_drop();

revoke all on function private.drop_deadline(jsonb) from public, anon, authenticated;
revoke all on function private.drop_amount(text, numeric) from public, anon, authenticated;
revoke all on function private.record_drop(uuid, text, text, text, text, text) from public, anon, authenticated;
revoke all on function public.record_entry_drop() from public, anon, authenticated;
revoke all on function public.record_judge_drop() from public, anon, authenticated;
revoke all on function public.guard_entry_drop() from public, anon, authenticated;

alter table public.entry_drops enable row level security;
revoke all on public.entry_drops from anon, authenticated;
grant select on public.entry_drops to authenticated;
grant update (waived, waive_reason) on public.entry_drops to authenticated;

drop policy if exists "Director and the school's coach read drops" on public.entry_drops;
create policy "Director and the school's coach read drops" on public.entry_drops for select to authenticated
  using (private.is_director(tournament_id) or lower(btrim(school)) = (select private.approved_coach_school(tournament_id)));
drop policy if exists "Director waives drops" on public.entry_drops;
create policy "Director waives drops" on public.entry_drops for update to authenticated
  using (private.is_director(tournament_id)) with check (private.is_director(tournament_id));
-- No insert or delete policy: only the triggers above (running as the table owner) write drops.


-- ═════════ supabase/paper_ballots.sql ═════════
-- Orator: paper ballots entered by the tab room.
-- Run in the Supabase SQL Editor after schema.sql, ballots.sql, tournaments.sql, fixes.sql,
-- calendar.sql and public_results.sql. Safe to run again. Run it again whenever you re-run
-- ballots.sql or tournaments.sql, because it replaces three trigger functions those files define.
--
-- Many judges still fill in paper ballots. The director (tab staff signed in as the director)
-- types each one in. A paper ballot is stored in the same ballots / ballot_entries tables as an
-- e-ballot, already submitted and attributed to the room's judge, so it counts in breaks, finals
-- and placings exactly like an e-ballot, coaches read it like any other ballot for their school,
-- and students see it once the tournament has finished and their coach has released results.
-- Paper ballots have no comments, reasons or private notes: only ranks, points, times and penalties.
--
-- Writes go through public.enter_paper_ballot(), which checks that the caller directs the
-- tournament and checks the ballot the way the e-ballot does (ranks 1..n with no ties, points
-- 35–50, a higher rank never has fewer points unless the lower-ranked speaker had a time penalty).
-- Every entry, correction and e-ballot override is logged in public.paper_ballot_log.

create schema if not exists private;

-- ── Where a ballot came from ──
alter table public.ballots add column if not exists source text not null default 'judge';
alter table public.ballots add column if not exists entered_by uuid references auth.users (id) on delete set null;
alter table public.ballots add column if not exists entered_by_name text not null default '';
alter table public.ballots add column if not exists entered_at timestamptz;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'ballots_source_check') then
    alter table public.ballots add constraint ballots_source_check check (source in ('judge', 'paper'));
  end if;
end $$;
create index if not exists ballots_by_section on public.ballots (section_id);

-- ── Log of every paper entry, correction and override ──
create table if not exists public.paper_ballot_log (
  id bigint generated always as identity primary key,
  ballot_id uuid references public.ballots (id) on delete cascade,
  tournament_id uuid not null references public.tournaments (id) on delete cascade,
  section_id uuid references public.sections (id) on delete set null,
  action text not null check (action in ('entered', 'corrected', 'override', 'replaced-draft')),
  actor uuid references auth.users (id) on delete set null,
  actor_name text not null default '',
  note text not null default '',
  previous jsonb,                     -- ranks, points and times before the change (never comments or private notes)
  entries jsonb not null,             -- what was entered
  created_at timestamptz not null default now()
);
create index if not exists paper_ballot_log_by_tournament on public.paper_ballot_log (tournament_id, created_at desc);

alter table public.paper_ballot_log enable row level security;
revoke all on public.paper_ballot_log from anon, authenticated;
grant select on public.paper_ballot_log to authenticated;
drop policy if exists "Directors read their paper ballot log" on public.paper_ballot_log;
create policy "Directors read their paper ballot log" on public.paper_ballot_log for select to authenticated
  using (private.is_director(tournament_id));

-- ── A pass that lets enter_paper_ballot() write a submitted ballot for another person ──
-- The ballot triggers below step aside only while this transaction holds a pass. Only
-- enter_paper_ballot() (security definer) can write here: nobody else has any rights on the table.
create table if not exists private.paper_entry_pass (
  tx bigint primary key,
  created_at timestamptz not null default now()
);
alter table private.paper_entry_pass enable row level security;
revoke all on private.paper_entry_pass from public, anon, authenticated;

create or replace function private.paper_entry_active() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from private.paper_entry_pass p where p.tx = txid_current());
$$;
revoke all on function private.paper_entry_active() from public, anon;
grant execute on function private.paper_entry_active() to authenticated;

-- ── Ballot triggers, replaced with a paper-entry pass. Every earlier rule is kept as it was. ──

-- From ballots.sql, plus: a judge can't mark their own ballot as paper or as entered by someone else.
create or replace function public.stamp_ballot() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if private.paper_entry_active() then
    new.updated_at := now();
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.judge_id := auth.uid();
    new.judge_name := coalesce((select p.full_name from public.profiles p where p.id = auth.uid()), '');
    new.status := 'draft';
    new.submitted_at := null;
    new.source := 'judge';
    new.entered_by := null;
    new.entered_by_name := '';
    new.entered_at := null;
  else
    new.judge_id := old.judge_id;
    new.judge_name := old.judge_name;
    new.created_at := old.created_at;
    new.source := old.source;
    new.entered_by := old.entered_by;
    new.entered_by_name := old.entered_by_name;
    new.entered_at := old.entered_at;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

-- From ballots.sql, with two changes: the pass (enter_paper_ballot() checks paper ballots itself), and section marks
-- are optional: a judge may give just a score out of 50.
create or replace function public.check_ballot_submission() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  problem text;
begin
  if private.paper_entry_active() then return new; end if;
  if new.status = 'submitted' and old.status = 'draft' then
    select case
      when count(*) = 0 then 'The ballot has no speakers.'
      when bool_or(e.present is null) then 'Every speaker must be marked present or no-show.'
      when bool_or(e.present and e.time_seconds is null) then 'Every speaker needs a time.'
      when bool_or(e.present and char_length(btrim(e.comments)) + char_length(btrim(e.reason)) < 40) then 'Every speaker needs at least 40 characters of comments and reason for decision.'
      -- Every speaker who performed needs a score out of 50 (the NSAA scale starts at 35; lower scores are recorded as 35).
      when bool_or(e.present and (e.rating is null or e.rating < 35 or e.rating > 50)) then 'Every speaker needs a score from 35 to 50.'
      -- Section marks are optional. If a judge marks sections, they mark all five (1 to 10) and the score is their total.
      when bool_or(e.present and coalesce((select bool_or(m is not null and m <> 0) from unnest(e.section_marks) m), false)
        and (cardinality(e.section_marks) <> 5 or exists (select 1 from unnest(e.section_marks) m where m is null or m < 1 or m > 10))) then 'Mark all five sections from 1 to 10, or none.'
      when bool_or(e.present and coalesce((select bool_or(m is not null and m <> 0) from unnest(e.section_marks) m), false)
        and e.rating is distinct from greatest(35, (select sum(m) from unnest(e.section_marks) m)::int)) then 'When sections are marked, the score must equal their total.'
      when bool_or(e.present and e.rank is null) then 'Every speaker who performed needs a rank.'
      when count(*) filter (where e.present) <> count(distinct e.rank) filter (where e.present) then 'There may be no ties in rank.'
      when coalesce(max(e.rank) filter (where e.present), 0) <> count(*) filter (where e.present) then 'Ranks must run from 1 with no gaps.'
    end into problem
    from public.ballot_entries e where e.ballot_id = new.id;
    if problem is null and exists (
      select 1 from public.ballot_entries a join public.ballot_entries b on b.ballot_id = a.ballot_id
      where a.ballot_id = new.id and a.present and b.present and a.rank < b.rank and a.rating < b.rating and not b.time_penalty  -- a time penalty lowers an entry one rank
    ) then problem := 'A speaker with a lower rating is ranked above one with a higher rating.'; end if;
    if problem is not null then raise exception '%', problem using errcode = 'check_violation'; end if;
    new.submitted_at := now();
  end if;
  return new;
end;
$$;

-- From tournaments.sql, plus: once the tab room has entered a paper ballot for a room, a judge
-- can't add a second ballot for it (it would count twice).
create or replace function public.check_ballot_room() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if private.paper_entry_active() then return new; end if;
  if new.section_id is not null and not exists (select 1 from public.sections s where s.id = new.section_id and s.tournament_id = new.tournament_id and s.judge_id = auth.uid()) then
    raise exception 'You are not the judge assigned to that room.' using errcode = 'insufficient_privilege';
  end if;
  if new.section_id is not null and exists (select 1 from public.ballots b where b.section_id = new.section_id and b.source = 'paper' and b.status = 'submitted') then
    raise exception 'The tab room already entered the paper ballot for this room.' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

drop trigger if exists stamp_ballot on public.ballots;
create trigger stamp_ballot before insert or update on public.ballots
  for each row execute function public.stamp_ballot();
drop trigger if exists check_ballot_submission on public.ballots;
create trigger check_ballot_submission before update on public.ballots
  for each row execute function public.check_ballot_submission();
drop trigger if exists check_ballot_room on public.ballots;
create trigger check_ballot_room before insert on public.ballots
  for each row execute function public.check_ballot_room();
revoke all on function public.stamp_ballot() from public, anon, authenticated;
revoke all on function public.check_ballot_submission() from public, anon, authenticated;
revoke all on function public.check_ballot_room() from public, anon, authenticated;

-- ── Entering (or correcting) one room's paper ballot ──
-- entries: one object per speaker in the room:
--   {"code": "<entry id>", "present": true, "rank": 1, "rating": 47 | null, "time_seconds": 581 | null,
--    "time_penalty": false, "marks": [9, 9, 10, 9, 10] | []}
-- override: needed to replace a ballot the judge already submitted electronically.
-- Returns the ballot's id.
create or replace function public.enter_paper_ballot(target_section uuid, entries jsonb, override boolean default false, note text default '')
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  s public.sections;
  t public.tournaments;
  me uuid := auth.uid();
  me_name text;
  judge uuid;
  judge_label text;
  existing public.ballots;
  problem text;
  present_count int;
  ballot uuid;
  action text := 'entered';
  prior jsonb;
  clean jsonb;
begin
  if me is null then raise exception 'Sign in first.' using errcode = 'insufficient_privilege'; end if;
  select * into s from public.sections where id = target_section;
  if s.id is null then raise exception 'That room is no longer on the schedule.' using errcode = 'no_data_found'; end if;
  select * into t from public.tournaments where id = s.tournament_id;
  if t.director_id is distinct from me then
    raise exception 'Only the tournament director can enter paper ballots.' using errcode = 'insufficient_privilege';
  end if;
  if t.status = 'finished' then
    raise exception 'The tournament has ended, so its ballots are locked.' using errcode = 'check_violation';
  end if;
  if jsonb_typeof(entries) is distinct from 'array' then raise exception 'The ballot has no speakers.' using errcode = 'check_violation'; end if;

  -- One row per speaker, in a shape the checks can read.
  create temporary table if not exists pg_temp.paper_rows (code text, present boolean, rank int, rating int, time_seconds int, time_penalty boolean, marks int[]) on commit drop;
  truncate pg_temp.paper_rows;
  insert into pg_temp.paper_rows
  select x ->> 'code', (x ->> 'present')::boolean, (x ->> 'rank')::int, (x ->> 'rating')::int, (x ->> 'time_seconds')::int,
         coalesce((x ->> 'time_penalty')::boolean, false),
         coalesce((select array_agg(m::int) from jsonb_array_elements_text(case when jsonb_typeof(x -> 'marks') = 'array' then x -> 'marks' else '[]'::jsonb end) m), '{}')
  from jsonb_array_elements(entries) x;

  select count(*) filter (where r.present) into present_count from pg_temp.paper_rows r;
  select case
    when count(*) = 0 then 'The ballot has no speakers.'
    when bool_or(r.code is null or not (r.code = any (s.entry_ids::text[]))) then 'A speaker on this ballot isn''t in this room.'
    when count(distinct r.code) <> count(*) then 'A speaker appears twice on this ballot.'
    when count(*) <> cardinality(s.entry_ids) then 'Every speaker in the room needs a line: a rank, or no-show.'
    when bool_or(r.present is null) then 'Every speaker must be marked present or no-show.'
    when bool_or(not r.present and (r.rank is not null or r.rating is not null)) then 'A no-show can''t have a rank or points.'
    when bool_or(r.present and r.rank is null) then 'Every speaker who performed needs a rank.'
    when bool_or(r.present and (r.rank < 1 or r.rank > present_count)) then format('Ranks must run from 1 to %s.', present_count)
    when count(distinct r.rank) filter (where r.present) <> present_count then 'There may be no ties in rank.'
    when bool_or(r.rating is not null and (r.rating < 35 or r.rating > 50)) then 'Points must be from 35 to 50.'
    when bool_or(cardinality(r.marks) > 0 and (cardinality(r.marks) <> 5 or exists (select 1 from unnest(r.marks) m where m is null or m < 1 or m > 10))) then 'Section marks need five marks from 1 to 10.'
    when bool_or(cardinality(r.marks) > 0 and r.rating is distinct from greatest(35, (select sum(m) from unnest(r.marks) m)::int)) then 'Points must equal the total of the section marks.'
    when bool_or(r.time_seconds is not null and (r.time_seconds < 0 or r.time_seconds > 3600)) then 'A time must be between 0:00 and 60:00.'
  end into problem from pg_temp.paper_rows r;
  if problem is null and exists (
    select 1 from pg_temp.paper_rows a join pg_temp.paper_rows b on a.present and b.present
    where a.rank < b.rank and a.rating < b.rating and not b.time_penalty  -- a time penalty lowers an entry one rank
  ) then problem := 'A speaker with fewer points is ranked above one with more points. Check the ballot, or mark the time penalty.'; end if;
  if problem is not null then raise exception '%', problem using errcode = 'check_violation'; end if;

  select jsonb_agg(jsonb_build_object('code', r.code, 'present', r.present, 'rank', r.rank, 'rating', r.rating, 'time_seconds', r.time_seconds, 'time_penalty', r.time_penalty, 'marks', to_jsonb(r.marks)) order by array_position(s.entry_ids::text[], r.code))
    into clean from pg_temp.paper_rows r;

  me_name := coalesce((select nullif(p.full_name, '') from public.profiles p where p.id = me), 'Director');
  judge := coalesce(s.judge_id, me);
  judge_label := coalesce(nullif(s.judge_name, ''), (select nullif(p.full_name, '') from public.profiles p where p.id = s.judge_id), '');

  -- The ballot already on file for this room: by room, or the judge's own ballot for the same round and room.
  select * into existing from public.ballots b
  where b.section_id = s.id or (b.judge_id = judge and b.tournament = t.name and b.round = s.round and b.room = s.room)
  order by (b.status = 'submitted') desc, (b.source = 'paper') desc, b.created_at
  limit 1;
  if existing.id is not null then
    if existing.source = 'paper' then action := 'corrected';
    elsif existing.status = 'submitted' then
      if not coalesce(override, false) then
        raise exception 'The judge already submitted an e-ballot for this room. Choose to override it if the paper ballot is the one that counts.' using errcode = 'check_violation';
      end if;
      action := 'override';
    else action := 'replaced-draft';
    end if;
    select jsonb_agg(jsonb_build_object('code', e.speaker_code, 'present', e.present, 'rank', e.rank, 'rating', e.rating, 'time_seconds', e.time_seconds, 'time_penalty', e.time_penalty) order by e.rank nulls last)
      into prior from public.ballot_entries e where e.ballot_id = existing.id;
  end if;

  insert into private.paper_entry_pass (tx) values (txid_current()) on conflict (tx) do nothing;

  if existing.id is not null then
    ballot := existing.id;
    update public.ballots set
      tournament_id = s.tournament_id, section_id = s.id, event_id = s.event_id, status = 'submitted',
      submitted_at = case when existing.status = 'submitted' then existing.submitted_at else now() end,
      source = 'paper', entered_by = me, entered_by_name = me_name, entered_at = now()
    where id = ballot;
    delete from public.ballot_entries where ballot_id = ballot;
  else
    insert into public.ballots (judge_id, judge_name, tournament, round, room, event_id, class_a, status, submitted_at, tournament_id, section_id, source, entered_by, entered_by_name, entered_at)
    values (judge, judge_label, t.name, s.round, s.room, s.event_id, false, 'submitted', now(), s.tournament_id, s.id, 'paper', me, me_name, now())
    returning id into ballot;
  end if;

  insert into public.ballot_entries (ballot_id, speaker_code, speaker_name, school, present, rank, rating, time_seconds, time_penalty, section_marks, comments, reason, disqualifications)
  select ballot, r.code, coalesce(e.student, r.code), coalesce(e.school, ''), r.present, r.rank, r.rating, r.time_seconds, r.time_penalty, r.marks, '', '', '{}'
  from pg_temp.paper_rows r left join public.entries e on e.id::text = r.code and e.tournament_id = s.tournament_id;

  insert into public.paper_ballot_log (ballot_id, tournament_id, section_id, action, actor, actor_name, note, previous, entries)
  values (ballot, s.tournament_id, s.id, action, me, me_name, left(coalesce(note, ''), 500), prior, clean);

  delete from private.paper_entry_pass where tx = txid_current();
  return ballot;
end;
$$;
revoke all on function public.enter_paper_ballot(uuid, jsonb, boolean, text) from public, anon;
grant execute on function public.enter_paper_ballot(uuid, jsonb, boolean, text) to authenticated;


-- ═════════ supabase/tabsheet.sql ═════════
-- Orator: live tab sheets.
-- Run in the Supabase SQL Editor after every file up to paper_ballots.sql, and before alerts.sql
-- (see the order in README.md). Safe to run again. Re-run it whenever you re-run tournaments.sql.
--
-- A tab sheet shows each preliminary round's rank and score for every speaker as ballots arrive,
-- their cumulative rank and current place, and which rooms are still out.
--
-- Who sees what (all enforced here, in public.tab_sheet):
--   * the director: every school;
--   * tab-room staff (approved coaches the director marks with tournament_members.tab_staff): every school, read-only;
--   * every other approved coach: their own school's speakers only (with each speaker's place in the contest);
--   * students, judges, everyone else: nothing.
-- Only submitted ballots count. Comments, reasons and private notes are never returned, and the
-- ballots / ballot_entries tables are not opened any wider: everything goes through tab_sheet().

create schema if not exists private;

-- ── Tab-room staff: only the director can set it, and only on an approved coach ──
alter table public.tournament_members add column if not exists tab_staff boolean not null default false;

create or replace function public.guard_tab_staff() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.tab_staff := false;               -- nobody asks to join as tab staff
    return new;
  end if;
  if not private.is_director(old.tournament_id) then
    new.tab_staff := old.tab_staff;       -- a coach can't make themselves (or anyone) tab staff
    return new;
  end if;
  if new.tab_staff and not old.tab_staff and (old.role <> 'coach' or new.status <> 'approved') then
    raise exception 'Only an approved coach can be tab-room staff.' using errcode = 'check_violation';
  end if;
  -- Removing a coach's access also ends their tab-room access.
  if old.role <> 'coach' or new.status <> 'approved' then new.tab_staff := false; end if;
  return new;
end;
$$;
drop trigger if exists guard_tab_staff on public.tournament_members;
create trigger guard_tab_staff before insert or update on public.tournament_members
  for each row execute function public.guard_tab_staff();
revoke all on function public.guard_tab_staff() from public, anon, authenticated;

-- ── The tab sheet: one row per (entry, preliminary round) ──
-- place / field: the speaker's current place in their contest among speakers with at least one rank,
-- worked out from every school's submitted ballots with the NSAA order the app uses (results.ts
-- prelimStandings): cumulative rank, opponents' average rank, head-to-head (an exact two-way tie),
-- reciprocals, rating points. A coach gets their own speakers' places, never anyone else's ranks.
drop function if exists public.tab_sheet(uuid);
create function public.tab_sheet(target uuid)
returns table (
  entry_id uuid, student text, school text, event_id text, division text,
  round int, section_id uuid, section_label text, room text, judge_name text, speak_order int,
  rank int, rating int, present boolean, submitted boolean, place int, field int
)
language sql stable security definer set search_path = '' as $$
  with viewer as (
    select private.is_director(target) as director,
      exists (select 1 from public.tournament_members m
              where m.tournament_id = target and m.user_id = (select auth.uid())
                and m.role = 'coach' and m.status = 'approved' and m.tab_staff) as staff,
      private.approved_coach_school(target) as school,
      coalesce(private.tournament_status(target), 'registration') as status
  ),
  seats as (
    select s.id as section_id, s.round, s.event_id, s.division, s.label, s.room,
      coalesce(nullif(s.judge_name, ''), (select p.full_name from public.profiles p where p.id = s.judge_id), '') as judge_name,
      u.entry_id, u.ord::int as speak_order, e.student, e.school
    from public.sections s
    join public.tournaments t on t.id = s.tournament_id
    cross join lateral unnest(s.entry_ids) with ordinality as u(entry_id, ord)
    join public.entries e on e.id = u.entry_id and e.tournament_id = s.tournament_id
    where s.tournament_id = target and s.round <= t.rounds and coalesce(s.stage, 'prelim') = 'prelim'
  ),
  -- The ballot that counts for each room: submitted only (a paper ballot the tab room entered wins).
  counted as (
    select distinct on (b.section_id) b.id, b.section_id
    from public.ballots b
    where b.tournament_id = target and b.status = 'submitted' and b.section_id in (select seats.section_id from seats)
    order by b.section_id, (b.source = 'paper') desc, b.submitted_at desc nulls last
  ),
  lines as (
    select seats.*, c.id is not null as submitted, be.present,
      case when be.present then be.rank end as rank,
      case when be.present then be.rating end as rating
    from seats
    left join counted c on c.section_id = seats.section_id
    left join public.ballot_entries be on be.ballot_id = c.id and be.speaker_code = seats.entry_id::text
  ),
  res as (
    select l.entry_id, l.section_id, l.event_id, l.division, l.rank, coalesce(l.rating, 0) as rating
    from lines l where l.submitted and l.present and l.rank is not null
  ),
  stats as (
    select r.entry_id, r.event_id, r.division, sum(r.rank)::int as cum, count(*)::int as n,
      round(sum(1.0 / r.rank), 4) as recip, sum(r.rating)::int as pts
    from res r group by r.entry_id, r.event_id, r.division
  ),
  -- Opponents' average rank: the average of the average ranks of everyone this speaker shared a ranked room with.
  opp as (
    select r.entry_id, round(avg(coalesce(st.cum::numeric / nullif(st.n, 0), 0)), 4) as opp
    from res r
    join seats o on o.section_id = r.section_id and o.entry_id <> r.entry_id
    left join stats st on st.entry_id = o.entry_id
    group by r.entry_id
  ),
  keyed as (
    select st.*, coalesce(op.opp, 0) as opp,
      count(*) over (partition by st.event_id, st.division, st.cum, coalesce(op.opp, 0)) as tied
    from stats st left join opp op on op.entry_id = st.entry_id
  ),
  -- Head-to-head, only for an exact two-way tie: the one ranked lower every time they met goes behind.
  h2h as (
    select a.entry_id, case when bool_and(ra.rank > rb.rank) then 1 else 0 end as behind
    from keyed a
    join keyed b on b.event_id = a.event_id and b.division = a.division and b.cum = a.cum and b.opp = a.opp and b.entry_id <> a.entry_id
    join res ra on ra.entry_id = a.entry_id
    join res rb on rb.entry_id = b.entry_id and rb.section_id = ra.section_id
    where a.tied = 2
    group by a.entry_id
  ),
  placed as (
    select k.entry_id,
      rank() over (partition by k.event_id, k.division order by k.cum, k.opp, coalesce(h.behind, 0), k.recip desc, k.pts desc)::int as place,
      count(*) over (partition by k.event_id, k.division)::int as field
    from keyed k left join h2h h on h.entry_id = k.entry_id
  )
  select l.entry_id, l.student, l.school, l.event_id, l.division, l.round, l.section_id, l.label, l.room, l.judge_name, l.speak_order,
    l.rank, l.rating, l.present, l.submitted, p.place, p.field
  from lines l
  cross join viewer v
  left join placed p on p.entry_id = l.entry_id
  where v.director
     or (v.status <> 'registration' and (v.staff or lower(l.school) = v.school))
  order by l.event_id, l.division, l.round, l.section_id, l.speak_order;
$$;
revoke all on function public.tab_sheet(uuid) from public, anon;
grant execute on function public.tab_sheet(uuid) to authenticated;


-- ═════════ supabase/alerts.sql ═════════
-- Text and email alerts. Run after schema.sql, ballots.sql, tournaments.sql, fixes.sql, calendar.sql and
-- public_results.sql: SQL Editor → New query → paste → Run. Safe to run again.
--
-- Each person chooses, on their own Alerts page, whether Orator may text them (with their phone number and
-- consent) or email them (their account email), and which alerts they want. When the director publishes the
-- schedule, presses "Send room alerts" for a round, swaps a judge after publishing, or opens or closes entries,
-- Postgres writes one row per recipient and channel into `notifications`. The messages are built here, from
-- the schedule itself: the director never types a message and can't choose who receives it. Only approved
-- members of that tournament who opted in get a row. The send-notifications Edge Function
-- (supabase/functions/send-notifications) delivers the rows with Twilio and Resend and marks them sent or failed.
-- Everything also shows in Orator itself (the "Schedule updated" banner), so nothing depends on texts working.

-- Internal helpers live in their own schema. Signed-in users get no access to it at all, so they can't call
-- the helper that queues a message (tournaments.sql grants execute on everything in `private`, so not there).
create schema if not exists alerts_internal;
revoke all on schema alerts_internal from public, anon, authenticated;

-- ── Each person's settings. One row per account.
create table if not exists public.notification_settings (
  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  phone text not null default '',                       -- +1 and ten digits, or '' for none
  sms_opt_in boolean not null default false,
  email_opt_in boolean not null default false,
  alert_rooms boolean not null default true,             -- students: my room before each round
  alert_ballots boolean not null default true,           -- judges: I have a ballot / room assignment
  alert_schedule boolean not null default true,          -- everyone: schedule published or changed
  alert_entries boolean not null default true,           -- coaches: entries opened or closed
  sms_consent_at timestamptz,                            -- when they agreed to texts
  sms_consent_text text not null default '',             -- the words they agreed to
  updated_at timestamptz not null default now(),
  constraint notification_phone_format check (phone = '' or phone ~ '^\+1[2-9][0-9]{2}[2-9][0-9]{6}$'),
  constraint notification_sms_needs_phone check (not sms_opt_in or phone <> '')
);

create or replace function public.stamp_notification_settings() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null then new.user_id := auth.uid(); end if;
  else
    new.user_id := old.user_id;
  end if;
  new.phone := btrim(new.phone);
  -- Consent is recorded when texts are switched on (or the number changes) and cleared when they're switched off.
  if new.sms_opt_in then
    if tg_op = 'INSERT' or not old.sms_opt_in or old.phone is distinct from new.phone or old.sms_consent_at is null then
      new.sms_consent_at := now();
    else
      new.sms_consent_at := old.sms_consent_at; new.sms_consent_text := old.sms_consent_text;
    end if;
    new.sms_consent_text := left(btrim(new.sms_consent_text), 500);
  else
    new.sms_consent_at := null; new.sms_consent_text := '';
  end if;
  new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists stamp_notification_settings on public.notification_settings;
create trigger stamp_notification_settings before insert or update on public.notification_settings
  for each row execute function public.stamp_notification_settings();
revoke all on function public.stamp_notification_settings() from public, anon, authenticated;

alter table public.notification_settings enable row level security;
revoke all on public.notification_settings from anon, authenticated;
grant select, insert, update, delete on public.notification_settings to authenticated;
drop policy if exists "People read their own alert settings" on public.notification_settings;
create policy "People read their own alert settings" on public.notification_settings for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists "People create their own alert settings" on public.notification_settings;
create policy "People create their own alert settings" on public.notification_settings for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists "People change their own alert settings" on public.notification_settings;
create policy "People change their own alert settings" on public.notification_settings for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
drop policy if exists "People remove their own alert settings" on public.notification_settings;
create policy "People remove their own alert settings" on public.notification_settings for delete to authenticated using (user_id = (select auth.uid()));

-- ── The outbox. Written only by the functions below; the Edge Function (service role) marks rows sent or failed.
create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  tournament_id uuid references public.tournaments (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  channel text not null check (channel in ('sms', 'email')),
  kind text not null check (kind in ('rooms', 'ballots', 'schedule', 'entries')),
  message text not null check (char_length(message) between 1 and 320),
  dedupe_key text not null,
  status text not null default 'queued' check (status in ('queued', 'sending', 'sent', 'failed')),
  error text not null default '',
  attempts int not null default 0,
  provider_id text not null default '',
  claimed_at timestamptz,
  created_at timestamptz not null default now(),
  sent_at timestamptz
);
create unique index if not exists notifications_dedupe on public.notifications (dedupe_key);
create index if not exists notifications_waiting on public.notifications (status, created_at) where status in ('queued', 'sending');
create index if not exists notifications_by_tournament on public.notifications (tournament_id, created_at desc);
create index if not exists notifications_by_user on public.notifications (user_id, created_at desc);

alter table public.notifications enable row level security;
revoke all on public.notifications from anon, authenticated;
grant select on public.notifications to authenticated;
drop policy if exists "Recipients and the director read alerts" on public.notifications;
create policy "Recipients and the director read alerts" on public.notifications for select to authenticated
  using (user_id = (select auth.uid()) or (tournament_id is not null and private.is_director(tournament_id)));

-- ── Building messages. Plain ASCII punctuation keeps a text in one 160-character segment.
create or replace function alerts_internal.site_url() returns text
language sql stable set search_path = '' as $$
  -- Set your own with: alter database postgres set app.site_url = 'https://your-site.example';
  select coalesce(nullif(current_setting('app.site_url', true), ''), 'https://orator-1rab.vercel.app');
$$;

create or replace function alerts_internal.event_name(event_id text) returns text
language sql immutable set search_path = '' as $$
  select case event_id
    when 'info' then 'Informative' when 'persuasive' then 'Persuasive' when 'extemp' then 'Extemp'
    when 'entertainment' then 'Entertainment' when 'oid' then 'OID' when 'poi' then 'POI' when 'poetry' then 'Poetry'
    when 'serious' then 'Serious' when 'humorous' then 'Humorous' when 'duet' then 'Duet Acting' when 'duo' then 'Duo'
    else event_id end;
$$;

-- Same times as roundTimes in src/tournament.ts.
create or replace function alerts_internal.round_time(round int) returns text
language sql immutable set search_path = '' as $$
  select (array['8:00 AM', '9:30 AM', '11:00 AM', '1:30 PM', '3:00 PM', '4:30 PM', '6:00 PM'])[least(greatest(round, 1), 7)];
$$;

-- The director's start time for a round (tournaments.settings.roundTimes), else the default above.
create or replace function alerts_internal.round_time(target uuid, round int) returns text
language sql stable security definer set search_path = '' as $$
  select coalesce(nullif(btrim((select t.settings->'roundTimes'->>(round - 1) from public.tournaments t where t.id = target)), ''), alerts_internal.round_time(round));
$$;

create or replace function alerts_internal.ordinal(n int) returns text
language sql immutable set search_path = '' as $$
  select n || case when n % 100 between 11 and 13 then 'th' when n % 10 = 1 then 'st' when n % 10 = 2 then 'nd' when n % 10 = 3 then 'rd' else 'th' end;
$$;

-- "Round 2 Informative", "Round 2 Novice Poetry", "Informative final".
create or replace function alerts_internal.room_label(s public.sections, prelim_rounds int) returns text
language sql immutable set search_path = '' as $$
  select case when s.round > prelim_rounds
    then (case when s.division = 'novice' then 'Novice ' else '' end) || alerts_internal.event_name(s.event_id) || ' final'
    else 'Round ' || s.round || ' ' || (case when s.division = 'novice' then 'Novice ' else '' end) || alerts_internal.event_name(s.event_id) end;
$$;

create or replace function alerts_internal.short_name(name text) returns text
language sql immutable set search_path = '' as $$
  select case when char_length(btrim(name)) > 60 then left(btrim(name), 57) || '...' else btrim(name) end;
$$;

-- Queue one message for one person, on each channel they opted into, if they are an approved member of the
-- tournament and want this kind of alert. The same message for the same reason is only ever queued once.
create or replace function alerts_internal.enqueue(target uuid, recipient uuid, alert text, body text, reason text, out queued int, out repeated int)
language plpgsql security definer set search_path = '' as $$
declare
  s public.notification_settings;
  channel text;
  added int;
  email text;
begin
  queued := 0; repeated := 0;
  if recipient is null or not exists (select 1 from public.tournament_members m where m.tournament_id = target and m.user_id = recipient and m.status = 'approved') then return; end if;
  select * into s from public.notification_settings ns where ns.user_id = recipient;
  if s.user_id is null then return; end if;
  if not (case alert when 'rooms' then s.alert_rooms when 'ballots' then s.alert_ballots when 'schedule' then s.alert_schedule when 'entries' then s.alert_entries else false end) then return; end if;
  select u.email into email from auth.users u where u.id = recipient;
  foreach channel in array array['sms', 'email'] loop
    continue when channel = 'sms' and not (s.sms_opt_in and s.phone <> '');
    continue when channel = 'email' and not (s.email_opt_in and coalesce(email, '') <> '');
    insert into public.notifications (tournament_id, user_id, channel, kind, message, dedupe_key)
    values (target, recipient, channel, alert, left(body, 320), concat_ws(':', target, recipient, channel, reason, md5(body)))
    on conflict (dedupe_key) do nothing;
    get diagnostics added = row_count;
    queued := queued + added; repeated := repeated + 1 - added;
  end loop;
end;
$$;

-- Where a claimed row goes right now: their phone or email, or null if they have since turned it off.
create or replace function alerts_internal.address_of(recipient uuid, channel text, alert text) returns text
language sql stable security definer set search_path = '' as $$
  select case
    when not (case alert when 'rooms' then s.alert_rooms when 'ballots' then s.alert_ballots when 'schedule' then s.alert_schedule when 'entries' then s.alert_entries else false end) then null
    when channel = 'sms' and s.sms_opt_in and s.phone <> '' then s.phone
    when channel = 'email' and s.email_opt_in then nullif((select u.email from auth.users u where u.id = recipient), '')
  end
  from public.notification_settings s where s.user_id = recipient;
$$;

-- An in-app note in the existing "Schedule updated" banner, once per wording.
create or replace function alerts_internal.post_update(target uuid, kind text, body text) returns void
language sql security definer set search_path = '' as $$
  insert into public.tournament_updates (tournament_id, kind, message)
  select target, kind, left(body, 300)
  where not exists (select 1 from public.tournament_updates u where u.tournament_id = target and u.message = left(body, 300) and u.created_at > now() - interval '12 hours');
$$;

revoke all on all functions in schema alerts_internal from public, anon, authenticated;

-- ── Round alerts. The director presses "Send room alerts for Round N" (rounds have no explicit start).
-- Each student gets their room, time and speaking position for each event; each judge gets their room and
-- a link to the ballot. Pressing again sends nothing new unless a room or speaking order has changed.
create or replace function public.queue_round_alerts(target uuid, round_number int) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.tournaments;
  s public.sections;
  r record;
  q record;
  label text;
  total int := 0; again int := 0; students int := 0; judges int := 0; unmatched int := 0; rooms int := 0;
begin
  select * into t from public.tournaments where id = target;
  if t.id is null or t.director_id is distinct from auth.uid() then
    raise exception 'Only this tournament''s director can send alerts.' using errcode = 'insufficient_privilege';
  end if;
  if t.status not in ('scheduled', 'running') then
    raise exception 'Publish the schedule before sending room alerts.' using errcode = 'check_violation';
  end if;
  for s in select * from public.sections where tournament_id = target and round = round_number order by position loop
    rooms := rooms + 1;
    label := alerts_internal.room_label(s, t.rounds);
    -- Students, matched to their entries by roster name (or account name) and school, as everywhere else.
    for r in
      select e.id as entry_id, slot.pos, m.user_id
      from unnest(s.entry_ids) with ordinality as slot(entry_id, pos)
      join public.entries e on e.id = slot.entry_id and e.tournament_id = target
      left join public.tournament_members m on m.tournament_id = target and m.role = 'student' and m.status = 'approved'
        and lower(btrim(m.school)) = lower(btrim(e.school)) and private.match_name(m) = lower(btrim(e.student))
    loop
      if r.user_id is null then unmatched := unmatched + 1; continue; end if;
      students := students + 1;
      select * into q from alerts_internal.enqueue(target, r.user_id, 'rooms',
        format('Orator: %s - %s at %s. You speak %s.', label, s.room, alerts_internal.round_time(s.tournament_id, s.round), alerts_internal.ordinal(r.pos::int)),
        format('round:%s:%s:%s', round_number, s.id, r.entry_id));
      total := total + q.queued; again := again + q.repeated;
    end loop;
    if s.judge_id is not null then
      judges := judges + 1;
      select * into q from alerts_internal.enqueue(target, s.judge_id, 'ballots',
        format('Orator: You''re judging %s in %s at %s. Open your ballot: %s', label, s.room, alerts_internal.round_time(s.tournament_id, s.round), alerts_internal.site_url()),
        format('round:%s:%s:judge', round_number, s.id));
      total := total + q.queued; again := again + q.repeated;
    end if;
  end loop;
  if rooms = 0 then raise exception 'There are no rooms in round %.', round_number using errcode = 'check_violation'; end if;
  perform alerts_internal.post_update(target, 'schedule', format('%s rooms are posted. Check your room and speaking order in Orator.', case when round_number > t.rounds then 'Final round' else 'Round ' || round_number end));
  return jsonb_build_object('queued', total, 'alreadyQueued', again, 'students', students, 'judges', judges, 'unmatched', unmatched, 'rooms', rooms);
end;
$$;
revoke all on function public.queue_round_alerts(uuid, int) from public, anon;
grant execute on function public.queue_round_alerts(uuid, int) to authenticated;

-- ── Automatic alerts. These fire on the director's own changes (row-level security already limits who can
-- make them), so the director never chooses recipients or wording.

-- Publishing the schedule (everyone who wants schedule alerts), and entries opening or closing (coaches).
create or replace function public.alert_tournament_change() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  m record;
  body text;
  fingerprint text;
begin
  if new.status = 'scheduled' and old.status = 'registration' then
    -- A republished schedule that is exactly the same isn't announced twice.
    select md5(coalesce(string_agg(concat_ws('|', s.round, s.event_id, s.room, s.judge_id, s.entry_ids::text), ',' order by s.position), '')) into fingerprint from public.sections s where s.tournament_id = new.id;
    body := format('Orator: The %s schedule is out. See your rooms and times: %s', alerts_internal.short_name(new.name), alerts_internal.site_url());
    for m in select distinct user_id from public.tournament_members where tournament_id = new.id and status = 'approved' loop
      perform alerts_internal.enqueue(new.id, m.user_id, 'schedule', body, 'published:' || fingerprint);
    end loop;
    perform alerts_internal.post_update(new.id, 'schedule', 'The schedule is published. Your rooms and times are in Orator.');
  end if;
  if new.entries_open is distinct from old.entries_open and new.status = 'registration' then
    body := case when new.entries_open
      then format('Orator: Entries for %s are open again. You can add and drop students until the director closes them.', alerts_internal.short_name(new.name))
      else format('Orator: Entries for %s are now closed. Report an issue in Orator if something still needs to change.', alerts_internal.short_name(new.name)) end;
    for m in select distinct user_id from public.tournament_members where tournament_id = new.id and status = 'approved' and role = 'coach' loop
      -- Pressing the button twice in the same minute only alerts once.
      perform alerts_internal.enqueue(new.id, m.user_id, 'entries', body, 'entries:' || to_char(date_trunc('minute', now()), 'YYYYMMDDHH24MI'));
    end loop;
  end if;
  return null;
end;
$$;
drop trigger if exists alert_tournament_change on public.tournaments;
create trigger alert_tournament_change after update of status, entries_open on public.tournaments
  for each row execute function public.alert_tournament_change();
revoke all on function public.alert_tournament_change() from public, anon, authenticated;

-- A judge swapped after the schedule is out: the new judge hears they have a ballot, the old judge that
-- they no longer do. Finals added later tell their judges too.
create or replace function public.alert_judge_change() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  t public.tournaments;
  label text;
  stamp text := to_char(date_trunc('minute', now()), 'YYYYMMDDHH24MI');
begin
  select * into t from public.tournaments where id = new.tournament_id;
  if t.status not in ('scheduled', 'running') then return null; end if;
  if tg_op = 'INSERT' and new.round <= t.rounds then return null; end if;
  if tg_op = 'UPDATE' and new.judge_id is not distinct from old.judge_id then return null; end if;
  label := alerts_internal.room_label(new, t.rounds);
  if new.judge_id is not null then
    perform alerts_internal.enqueue(t.id, new.judge_id, 'ballots',
      format('Orator: You''re %sjudging %s in %s at %s. Open your ballot: %s', case when tg_op = 'UPDATE' then 'now ' else '' end, label, new.room, alerts_internal.round_time(new.tournament_id, new.round), alerts_internal.site_url()),
      format('judge:%s:%s', new.id, stamp));
  end if;
  if tg_op = 'UPDATE' and old.judge_id is not null then
    perform alerts_internal.enqueue(t.id, old.judge_id, 'ballots',
      format('Orator: You''re no longer judging %s in %s. Your rooms are in Orator: %s', label, new.room, alerts_internal.site_url()),
      format('unjudge:%s:%s', new.id, stamp));
  end if;
  return null;
end;
$$;
drop trigger if exists alert_judge_change on public.sections;
create trigger alert_judge_change after insert or update of judge_id on public.sections
  for each row execute function public.alert_judge_change();
revoke all on function public.alert_judge_change() from public, anon, authenticated;

-- ── The director's Alerts summary: counts only, plus the latest errors. No phone numbers or emails.
create or replace function public.alert_summary(target uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  result jsonb;
begin
  if not private.is_director(target) then
    raise exception 'Only this tournament''s director can see its alerts.' using errcode = 'insufficient_privilege';
  end if;
  select jsonb_build_object(
    'queued', count(*) filter (where status = 'queued'),
    'sending', count(*) filter (where status = 'sending'),
    'sent', count(*) filter (where status = 'sent'),
    'failed', count(*) filter (where status = 'failed'),
    'oldestQueued', min(created_at) filter (where status = 'queued'),
    'lastSent', max(sent_at)
  ) into result from public.notifications where tournament_id = target;
  select result || jsonb_build_object(
    'members', count(distinct m.user_id),
    'optedIn', count(distinct m.user_id) filter (where (s.sms_opt_in and s.phone <> '') or s.email_opt_in),
    'textOptIns', count(distinct m.user_id) filter (where s.sms_opt_in and s.phone <> ''),
    'emailOptIns', count(distinct m.user_id) filter (where s.email_opt_in),
    'byRole', jsonb_build_object(
      'student', count(distinct m.user_id) filter (where m.role = 'student' and (s.sms_opt_in or s.email_opt_in)),
      'judge', count(distinct m.user_id) filter (where m.role = 'judge' and (s.sms_opt_in or s.email_opt_in)),
      'coach', count(distinct m.user_id) filter (where m.role = 'coach' and (s.sms_opt_in or s.email_opt_in))))
  into result
  from public.tournament_members m left join public.notification_settings s on s.user_id = m.user_id
  where m.tournament_id = target and m.status = 'approved';
  select result || jsonb_build_object('errors', coalesce(jsonb_agg(jsonb_build_object('channel', e.channel, 'kind', e.kind, 'error', e.error, 'at', e.created_at) order by e.created_at desc), '[]'::jsonb))
  into result
  from (select n.channel, n.kind, n.error, n.created_at from public.notifications n where n.tournament_id = target and n.status = 'failed' order by n.created_at desc limit 5) e;
  return result;
end;
$$;
revoke all on function public.alert_summary(uuid) from public, anon;
grant execute on function public.alert_summary(uuid) to authenticated;

-- ── Delivery, for the send-notifications Edge Function only (it runs with the service role key).
-- Claiming moves rows from queued to sending with FOR UPDATE SKIP LOCKED, so two runs at once never take the
-- same row. A row stuck in sending for ten minutes (the function crashed) is tried again, at most three times.
create or replace function public.claim_notifications(batch int default 50, channels text[] default array['sms', 'email'])
returns table (id uuid, channel text, address text, message text, kind text, attempts int)
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare
  r record;
  addr text;
begin
  update public.notifications n set status = 'failed', error = 'Gave up after 3 tries.'
  where n.status = 'sending' and n.claimed_at < now() - interval '10 minutes' and n.attempts >= 3;
  for r in
    with picked as (
      select n.id from public.notifications n
      where n.channel = any (channels) and (n.status = 'queued' or (n.status = 'sending' and n.claimed_at < now() - interval '10 minutes'))
      order by n.created_at
      limit greatest(1, least(coalesce(batch, 50), 500))
      for update skip locked
    )
    update public.notifications n set status = 'sending', claimed_at = now(), attempts = n.attempts + 1
    from picked where n.id = picked.id
    returning n.id, n.user_id, n.channel, n.message, n.kind, n.attempts
  loop
    addr := alerts_internal.address_of(r.user_id, r.channel, r.kind);
    if addr is null then
      update public.notifications n set status = 'failed', error = 'Not sent: the recipient turned this alert off.' where n.id = r.id;
    else
      id := r.id; channel := r.channel; address := addr; message := r.message; kind := r.kind; attempts := r.attempts;
      return next;
    end if;
  end loop;
end;
$$;

-- Record what happened to one claimed row. `retry` puts it back in the queue (a timeout or a 5xx from the provider).
create or replace function public.finish_notification(target uuid, ok boolean, failure text default '', provider text default '', retry boolean default false)
returns void
language sql security definer set search_path = '' as $$
  update public.notifications n set
    status = case when ok then 'sent' when retry and n.attempts < 3 then 'queued' else 'failed' end,
    error = case when ok then '' else left(coalesce(failure, ''), 500) end,
    provider_id = case when ok then left(coalesce(provider, ''), 120) else n.provider_id end,
    sent_at = case when ok then now() else n.sent_at end
  where n.id = target and n.status = 'sending';
$$;

revoke all on function public.claim_notifications(int, text[]) from public, anon, authenticated;
revoke all on function public.finish_notification(uuid, boolean, text, text, boolean) from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant usage on schema alerts_internal to service_role;
    grant execute on function public.claim_notifications(int, text[]) to service_role;
    grant execute on function public.finish_notification(uuid, boolean, text, text, boolean) to service_role;
    grant select, update on public.notifications to service_role;
  end if;
end $$;

